(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-3"] = [{"a": [36], "v": 1, "p": 156, "ev": 1, "ep": 160, "sid": 157, "t": "قوله - عز وجل -\n﴿فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ﴾⟪2:36⟫ الآية: (36) - سورة البقرة.\nزل، وزال يتقاربان، إلا أن زل يقتضي عثرة مع الزوال، يقال: زلت رجله في المشي ولسانه بالقول، وسمي الأسد إذلالا اعتبارا من الفاعل استقلاله حتى يعده عثرة، وقول النبي - عليه الصلاة والسلام: \" من أزلت إليه نعمة فليشكرها \" أي من أسدى إليه نعمه، وإن كانت طفيفة، وإزلال إبليس لآدم عليه السلام قوله له ﴿هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ﴾⟪20:120⟫ وقوله: ﴿مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ﴾⟪7:20⟫ ومقاسمته إياها بقوله: ﴿إِنِّي لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ﴾⟪7:21⟫ فمن الناس من حمل هذه الأحوال على مفاوضة ومجاراة بالمشاهدة وقيل: إن ذلك كان بوسوسته كما قال: ﴿فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ﴾⟪7:20⟫ وما روى عن ابن عباس - رضي الله عنهما - أن إبليس عرض نفسه على دواب الأرض أن تحمله فتدخله الجنة ليكلم آدم وزوجته، فأبت عليه الدواب كلها حتى كلم الحية وقال: أمنعك من بني آدم إن أنت أدخلتني الجنة، فجعلته بين نابين من أنيابها، فأدخلته الجنة وكلمها من فيها، قال: فلذلك أمر الإنسان بقتلها أينما وجدها فإن بعض الناس حمل ذلك على سبيل المثل، وقال: هذا إشارة، فقوله: عرض نفسه على\n⟦1:157⟧\nدواب الأرض، أي استعان بقوى الإنسان، ونظر من أي جهة يمكنه أن يأتيه، فلم يجد قوة مستصلحة يستعين بها حتى أتى الحية، أي الشهوة، وكنى بالحية عنها، فإنها حية لا يبرا سليمها [يقال لمن لسعته الحية والعقرب سليم تفاؤلا كما تقال المفازة لمحل الخطر والهلاك] وذاك أن الشيطان لا يأتي الإنسان إلا من قبل هواه، فجعلته بين نابيها كناية عن الأكل ، إذ هو أعظم شهوة يتمكن الشيطان به من الإنسان، ولهذا قيل في الخبر:\n(من حفظ بطنه فقد سد على الشيطان بابه ومن شبع ونام قسا قلبه وتمكن منه الشيطان) ويكون الهوى أعظم سلاح للشيطان، صار لا فرق بين قوله تعالى: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ﴾⟪38:26⟫ وقوله ﴿لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ﴾⟪19:44⟫ في أن المقصد واحد في كونهما نهيا عن ارتكاب الذنوب وقوله، فلذلك أمر الإنسان بقتلها، أي أمر أن يقهر الشهوة [ويذللها] حيثما تراءت له، وطالبته بما بنافي الإيمان، وهذا الذي ذكره هذا القائل وإن كان صحيحا من حيث المعنى، ففي صرف الخبر إليه ترك للظاهر وفتح باب من التأويلات عظيم الضرر.\nوالله أعلم بحقائق ما يخبرنا به من الغيوب ..\nوقوله: (اهبطوا): الهبوط ضد الصعود، وليس يراد به الانحدار عن رفعة مكانية\n⟦1:158⟧\nفقط، بل يراد به مع ذلك سقوط المنزلة، فقد كثر في كلامهم استعمال الرفعة والضعة في المراتب حتى قيل: شريف ووضيع على طريق الاستعارة، وعلى ذلك قول الشاعر:\nبلغنا السماء بأحسابنا\nوقال:\nوصاعد في هضاب المجد يطلعها\nوأما المعاداة: ففقدان الملاءمة والموافقة، ومنه قيل: \" هو مكان ذو عدوى \"، والتعدي والعدوان والاعتداء، والعدوى منها، وقوم عدى للأعداء أو الغرباء، لما بينهم من فقدان الملاءمة، وقوله تعالى: ﴿بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ﴾⟪43:67⟫ ليس يريد المهارشة فقط، وإنما يعني فقدان الالتئام، أما بين الشيطان والإنسان فظاهر، وبين الرجل والمرأة كثير في الخلق والخلق، حتى إن عامة ما يحمد من أخلاق الرجل يذم من المرأة، ثم بين قوى الإنسان في نفسه تفاوت، فحذرنا الله تعالى الذي خلقنا منها ليتنبه للاحتراز مما ينافينا في بلوغ السعادة، ونسوس منها ما يمكن سياسته، وندفع منها ما يجب مدافعته، والمستقر: المكان الذي يحصل فيه القرار، والقرار هو السكون عن برودة ولما كان من شأن البرودة السكون كما أن من شأن الحرارة الحركة قيل في الساكن برد، وفي المتحرك: اشتعل، والتهب، وحتى شبه السريع بنار متقدة، والساكن بماء جامد، وقوله ﴿وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ﴾⟪2:36⟫ كقوله: ﴿أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارٗا﴾⟪27:61⟫ وقوله: ﴿جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا﴾⟪2:22⟫ قيل معنى المستقر القبور، والآية محمولة عليها، فقد قال: ﴿أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا ۝ أَحۡيَآءٗ وَأَمۡوَٰتٗا﴾⟪77:25-26⟫ والمتاع: انتفاع\n⟦1:159⟧\nممتد الوقت، ومنه قيل: متعه الله بكذا، ومنه: متعة الحج، ومتعة المطلقة، ومتاع البيت، ومن قال: عنى به الحياة، فلأنه عمد إلى أشرف نوع من المتاع، ففسره به، ولحين وقت بلوغ الشيء ويتخصص بالمضاف إليه، ولما كان أحيان الأشياء يختلف، نظر بعض المفسرين إلى المضاف إليه لفظ الحين ففسره به، وقال: إنه يجئ على أوجه، فالحين: الأجل، لقوله: ﴿وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ﴾⟪10:98⟫ والسنة، لقوله: ﴿تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ﴾⟪14:25⟫ والساعة لقوله: ﴿حِينَ تُمۡسُونَ وَحِينَ تُصۡبِحُونَ﴾⟪30:17⟫ والزمان لقوله.\n﴿هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـٔٗا مَّذۡكُورًا﴾⟪76:1⟫ واختلاف ذلك لاختلاف المضاف إليه، وفي الآية تحذير من الشيطان كما قال: ﴿يَٰبَنِيٓ ءَادَمَ لَا يَفۡتِنَنَّكُمُ ٱلشَّيۡطَٰنُ كَمَآ أَخۡرَجَ أَبَوَيۡكُم مِّنَ ٱلۡجَنَّةِ﴾⟪7:27⟫ الآية والتحذير من كل غرور ومن الركون إلى الدنيا، والتنبيه على أنها دار ممر، وأن الآخرة دار مقر.\n[وبالله التوفيق]\n⟦1:160⟧"}, {"a": [37], "v": 1, "p": 160, "ev": 1, "ep": 163, "sid": 161, "t": "قوله - عز وجل -:\n﴿فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾⟪2:37⟫ الآية: (37) سورة البقرة.\nالتلقي كالتلقن، إلا أن التلقي يقتضي استقبال الكلام وتصوره، والتلقن يقتضي الحذق في تناوله، والتلقف يقاربه، لكن يقتضي الاحتيال في التناول، الكلم: التأثير المدرك بإحدى الحاستين السمع والبصر، فالكلام مدرك بحاسة السمع فكلمته: جرحته جراحة بأن أثرها ولاجتماعهما في ذلك قال الشاعر:\nوالكلم الأصيل كأرغب الكلم\nوقال:\nوجرح اللسان كجرح اليد.\nوالكلمات التي تلقاها آدم من ربه قيل: هي قوله: ﴿رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ﴾⟪7:23⟫ وقال الحسن: هو قوله: \" ألم تخلقني بيدك؟ ألم تسكنني جنتك؟ ألم تسجد لي ملائكتك؟ ألم تسبق رحمتك غضبك؟ فقال تعالى له: بلى، قال: أرايت إن تبت تبت علي وأعدتني\n⟦1:161⟧\nإلى الجنة؟ قال: نعم، فهذا يعني قوله: ﴿فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ﴾⟪2:37⟫ وقيل: إنه قال تعالى له: من أذنب ذنبا ثم تاب قبلت منه، وهذا يقارب الأول، وقيل: (إنها قبول الأمانة المعروضة على السماوات والأرض المذكور في قوله: ﴿إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا﴾⟪33:72⟫ الآية، وقيل: هو حروف التهجي وما تركب منها من الأسماء التي كانت قد علمها وما انتتج منها من العلوم الحقيقة والأعمال الفاضلة، فإن أصل الإيمان العلوم الصادقة والأعمال الصالحة، فمن الحروف تتركب مفردات الألفاظ، نحو: زيد، عمرو، وذهب، خرج، من، عن ومن المفردات تركب المقدمات المفردة، نحوك زيد خارج وعمرو ذاهب ومن المقدمات تتركب الأدلة والأخبار المؤلفة، ومن الأدلة المفردة الصادقة يتوصل إلى حقائق العلوم وبحقائق العلوم يتوصل إلى الأعمال الصالحة، وبمجموعها يحصل الإيمان الذي يتحققه، ويصير الإنسان تام التوبة متطهرا من النقيصة، محبوبا لرب العزة، كما قال تعالى: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ﴾⟪2:222⟫ والمتحقق بذلك لا محالة يتوب الله عليه، وقيل: إن هذه الكلمات هي التي ذكرها الله تعالى في قصة إبراهيم - عليه السلام - قال تعالى: ﴿وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ﴾⟪2:124⟫ وهي خصال مذكورة في ثلاثة مواضع من القرآن ..\nأحدها في سورة التوبة: ﴿ٱلتَّٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ﴾⟪9:112⟫ والثاني في قوله: ﴿قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ﴾⟪23:1⟫ والآيات إلى قوله: ﴿أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ ۝ ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪23:10-11⟫\n⟦1:162⟧\nوالثالث: في سورة \" سأل سائل \" وهو قوله: ﴿إِلَّا ٱلۡمُصَلِّينَ ۝ ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ﴾⟪70:22-23⟫ الآيات إلى قوله ﴿أُوْلَٰٓئِكَ فِي جَنَّٰتٖ مُّكۡرَمُونَ﴾⟪70:35⟫ فهذه الخصال الثلاث فرق من الناس العلماء والحكماء والكبراء المعنيين بقول النبي - صلى الله عليه وسلم - سائل العلماء وخالط الحكماء وجالس الكبراء ولكل فرقة مقامات معدودة يترتب بعضها على بعض، وهذه مسألة كثيرة قد أحكمتها في كتاب (شرف التصرف) وبينت تخصيص كل مقام وهذا القول والذي تقدمه يتقاربان عند الحقيقة، غير أن الأول نظر إلى المبدأ والثاني إلى الغاية، وذلك مذكور هناك، ثم التوبة: ترك الذنب على أحد الوجوه، وهو ضرب من الاعتذار فإن الاعتذار على ثلاثة أوجه إما أن يقول المعتذر: لم أفعل كذا، ويقول: فعلت لأجل كذا، أو يقول: فعلت وأسأت وقد أقلعت، ولا رابع لذلك وهذا الأخير هو التوبة، فإذا: التوبة ضرب من الاعتذار.\nوالتوبة والأوبة والاستغفار متقاربة وبحسب ما اختلفت فيها الاعتبارات اختلفت عليها العبارات، (الإنابة) الرجوع عن طريق الضلال إلى الهدى، والأوبة: رجوع القلب إلى الحق والوقوف عليه، والاستغفار: طلب الغفران قولان وفعلا، أي: تعاطي ما يغفر ما تقدم من الذنب، والتوبة التامة المعتد بها: ترك الذنب، والندم عليه، وهو العزم على أن لا يعود إليه، وتدارك ما تقدم وهو رد المظالم \" مظلمة الخلق، ومظلمة الخالق \" ومظلمة الخالق: هي إعادة ما ترك من العبادات وإذابة ما استفاد جسمه من الحرمات، ألا ترى إلى قوله [عليه السلام] \" كل لحم نبت من سحت النار أولى به \" والتواب: يقال في العبد، وفي الرب، لكن العبد تائب إلى الله - عز وجل - والله تائب على عبده، وقوله: ﴿إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾⟪2:37⟫ جمع بين الوصفين - تنبيها على أنه مع ترك ذنبه، عليه لا يخليه من\n⟦1:163⟧\nالإحسان إليه، ولم يقل: تاب عليهما لما تقدم أنه جعلها تابعة له، لا مقصوده في نفسها.\nوفي الآية تنبيه يعني هو أنه متى تلقينا منه ما أنعم به علينا من العلوم، واستعملناه واعترفنا بذنبنا وطلبنا منه التجاوز عنه ونحن في مهلة من الحياة تاب علينا وأحسن إلينا."}, {"a": [38], "v": 1, "p": 163, "ev": 1, "ep": 166, "sid": 164, "t": "قوله - عز وجل -:\n﴿قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعٗاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:38⟫\nالآية (38) - سورة البقرة.\nوالمجيء والإقبال والإتيان متقاربة غير أن المجيء عام والإقبال مجيء من ناحية القبل والإتيان مجيء عن بعد ومنه قيل: الآتي \" للغريب وللسبيل \" الجائي \" من بعيد، و \" أتيته \" أي: \" أعطيته \" منقول عن أتيته و \" اتوته \" وهما لغتان، والاتباع والإتلاء والاحتذاء والاقتداء تتقارب فالإتلاء: مجيء بعد أخر فاصل بينهما من جنسهما، والاحتذاء منقول من حذو الفعل بالفعل والاقتداء: اتباع على مدى، أي على قدر المتبع بلا تجاوز ولا تأخر، والاتباع عام في كل ذلك، ومنه قيل في الرعية \" أتباع \" و \" سمي العجل التابع لامه تبيع، والخوف والفزع والحذر والرهبة والهيبة والخشية والوجل والشفقة تتقارب فالخوف توقع مكروه عن أمارة وذلك للمذنب ولهذا قال أمير المؤمنين علي - رضي الله عنه -: \" لا يخافن امرؤ إلا ذنبه ولا يرجون إلا ربه \" والفزع: اضطراب عن وهم، كمن يسمع هدة فاضطرب، والحذر: خوف مع احتراز، والرهبة خوف مع اضطراب واحتراز والهيبة: رهبة مع استشعار تعظيم، والشفقة: خوف مع محبة، ولذلك قيل: الخوف والحذر للمذنب والرهبة للعابد والخشية للعالم، والهيبة للعارف والحزن خشونة تعتري النفس، مشتق من حزونة الأرض\n⟦1:164⟧\nولذلك يقال: خشنت بصدره، وقيل: الحزن والغضب من جنس واحد، وقد تقدم الكلام فيه.\nوالفائدة على تكرير قوله: (اهبطوا) لتكرير الشرط المقرون به، فإن الأول فرن بحال العداوة الثانية بينهم وسكونهم في الأرض إلى مدة متناهية، والثاني: بين به أنهم وإن اشتركوا في الهبوط، فهم متبانيون في الحكم فإن من اتبع هدايته فهو على سبيل الخلاص،\nإن قيل: لم لم يقل: فمن تبعه فيستغنى بالضمير عن التكرير، فقد استقبح في باب البلاغة تكرير اللفظة الواحدة في الجملة الواحدة حتى استرذل قول الشاعر:\nلا أرى الموت يسبق الموت شيء\n....\nتغص الموت ذا الغنا والفقيرا\nوقول آخر مع جودة معناه\nبجهل كجهل السيف والسيف منتضي ...\nوحلم كحلم السيف والسيف مغمد\nقيل: إن ذلك يستقبح إذا لم يحصل في الثاني معنى غير المعنى الأول كالبيت.\nوالآية بخلاف ذلك، فإن الهدى من الله ضربان، ضرب بالعقل، وضرب بقول الرسل، وأراد تعالى بقوله: ﴿فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى﴾⟪2:38⟫ ما يأتي على ألسنة الرسل - عليهم السلام -، ويقوله: هداي ما على لسانهم، وما كان من جهة العقل فنبه أن من أتاه رسول ورعاه مع رعايته لمقتضى العقل فهم الأولياء الذين لا خوف عليهم ولا هم يحزنون\nإن قيل: كيف نفى الخوف عن الأولياء في مواضع نحو قوله:\n⟦1:165⟧\n﴿أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪10:62⟫ ومدحهم بذلك في مواضع نحو قوله: ﴿وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ﴾⟪13:21⟫ وقوله: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾⟪17:57⟫ قيل أما نفي الخوف والحزن عنهم فقد قيل: لفظه الخبر، ومعناه: النهي كقوله : ﴿أَلَّا تَخَافُواْ وَلَا تَحۡزَنُواْ﴾⟪41:30⟫ وقيل هو خبر لكن مدحهم بها في الدنيا وحثهم عليها وأمنهم منها في الآخرة كما روى: \" من خاف الله في الدنيا أمنه الله في الآخرة \" وعلى ذلك حكى عنهم بقوله تعالى: ﴿وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ﴾⟪35:34⟫ أيضا: فإن الخوف الذي مدح به المؤمنين، وحثوا عليه ليس يراد به استشعار الرعب المترقب مضرته، وإنما يراد به فعل الخيرات المأمور بها المذكور في قوله: ﴿يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩﴾⟪16:50⟫، والكف عن المعاضي، منهي النفس عن الهوى المذكور في قوله:\n﴿وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ ۝ فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ﴾⟪79:40-41⟫\nوالخوف والحزن المنفيان عنهم استشعار الغم الذي يكون من ذوي العدوان، وكذلك روي: (لا يرجون امرؤ إلا ربه، ولا يخافن إلا ذنبه)\nوأيضا فالحزن إنما يكون لفوت محبوب، الخوف يكون لفقد مطلوب، والمتبع لهدي الله هو المؤمن الحكيم، الذي لا يقتنيي لنفسه فضولا من الأعراض، وما اقتناه لضروراته علم إنه يعرض الأعراض وأنه عارية مستردة، فلا يحزن على استرداها، ولا يطلب المستغني عنه، وما طلبه بعد وجوبه عليه طلبه عالما أن الله لا يبسط لأحد دنيا إلا اغترارا واختبارا، فإذا منح قام يحقوقه شاكرا، وإذا منع استغنى عنه صابرا، فهؤلاء لا خوف عليهم ولا هم يحزنون في دنياهم.\n⟦1:166⟧"}, {"a": [39], "v": 1, "p": 166, "ev": 1, "ep": 167, "sid": 167, "t": "قوله- عز وجل:\n﴿وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:39⟫ \" الأية (39) - سورة البقرة \"\nالاصطحاب، والاجتماع، والاقتران تتقارب، فالاجتماع أعم معنى، الاصطحاب: اجتماع مع طول لبث، والاقتران يقتضي شدا ما، إما صنعة، كاقتران بعير ببعير وإما حكمة، كاقتران الصديقين واصحب الرجل إدا صار ذا صاحب، ولما كان الأصحاب مقتضيا للانقياد، فسره أهل اللغة به، والتكذيب بالآيات بعض الكفر وتمامه، فإن فيه مع تعاطي الكفر بالفعل جحودآ باللسان\nوتخصيصه بعده نحو قوله تعالى: ﴿ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ﴾ في أن عمل الصالحات بعض الإيمان وتمامه، وليس يعني بالآيات القران فقط، بل يراد بها مع دلك الآيات التي في السماوات والأرض الدالة على الوحدانية المستحث على اعتبارها، بنحو قوله: ﴿وَكَأَيِّن مِّنۡ ءَايَةٖ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يَمُرُّونَ عَلَيۡهَا وَهُمۡ عَنۡهَا مُعۡرِضُونَ﴾⟪12:105⟫،\nإن قيل: لم قال ههنا: ﴿أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:39⟫ وقال في الحج: ﴿وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ﴾⟪22:57⟫ قيل: الاسم الموصول، والنكرة الموصوفة حتى ضمنتا معنى الشرط قد تدخل \" الفاء \" في خبرها تنبيها على معنى الشرط، ويجوز ترك ذلك منه بقول: والذي يأتيني له درهم، والذي يأتيني فله درهم \"،\n⟦1:167⟧"}, {"a": [40], "v": 1, "p": 167, "ev": 1, "ep": 169, "sid": 168, "t": "قوله - عز وجل -:\n﴿يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُواْ بِعَهۡدِيٓ أُوفِ بِعَهۡدِكُمۡ وَإِيَّٰيَ فَٱرۡهَبُونِ﴾⟪2:40⟫\nالآية: (40) - سورة البقرة.\nالابن: من البناء، وسمي بذلك لكونه كالمبنى لأبيه، وكل مصنوع ينسب إلى صانعه وآلته، فيقال هو ابنه، وللصانع يقال: هو أبوه، وعلى هذا يقال: فلان ابن الحرب، وأبو الحرب، وبتسمية الصانع أبا للمصنوع، والمصنوع ابنا للصانع أطلق على ما جكى في شريعة من تقدمنا \" أبناء الله \"، ثم تصور ذلك الجهلة والأغبياء معنى الولادة، فحظر إطلاق ذلك حتى صار التفوه به يعد كفرا، والوفاء مراعة العهد، والغدر تضييعه، كما أن الإنجاز مراعاة الوعد، والإخلاف تضييعه، الوفاء والإنجاز في الفعل كالصدق في المقال.\nوالعذر والاخلاف كالكذب فيه، وقيل: وفي وأوفى بمعنى، والصحيح أن أوفى أبلغ من وفي، كما أن: أسقى \" أبلغ من \" سقى \"، والخطاب وإن كان لبني إسرائيل لقولهم مقصودين بالتبكيت لنسيانهم نعم الله تعالى وكون نعمته عليهم أظهر، فالناس طرا يشاركونهم في وجوب ذكر نعمة عليهم، وقد تقدم ذكر تفاصيل النعم، وإن قيل: ما فائدة تقييد النعمة بقوله: أنعمت عليكم؟ قيل: نظر الإنسان إلى نعم الله ضربان، أحدهما: نظره إلى نهمة الله تعالى التي [تختص به من نفسه دون ما اختص به غيره] وذلك يفيده رضا عن النعم وشكرا له ومعرفة ما على غيره من النعم، والثاني: نظره إلى نعمة الله على غيره ونسيان ما قد خص به في نفسه، وذلك يجلب إليه سخطا على ربه، وكفرانا لآلائه، وحسدا على عباده، ولهذا قيل:\n\" انظر إلى من هو دونك، ولا تنظر إلى من هو فوقك، فذلك أجدر أن لا تزرى بنعمة ربك \".\n⟦1:168⟧\nوعهود الله كثيرة، بعضها مرتب على البعض، والوفاء بكل واحد مقابلة، فأول منزلته إظهار الشهادتين ويقابله من الله تعالى حقن الدماء والأموال كما قال - عليه السلام \" من قال: لا إلله إلا الله فقد عصم مني ماله ودمه \".\nوآخره ما كان من أولياء الله في حفظ النظرات والخطرات، ويقابله من الله تعالى: (ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر)، وبينهما وسائط كثيرة لها من الله تعالى مقابلات، ولما كان من مبدئه إلى منتهاه عرضا كثيرا نظر كل واحد من المفسرين للآية نظرا ما صارت به أقوالهم مختلفة في الظاهر بحسب اختلاف نظراتهم، فروي عن ابن عباس - رضي الله عنهما - أن الإشارة بذلك إلى قوله تعالى:\n﴿وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾⟪5:12⟫\nوروي عنه \" أوفوا بعهدي \" في اتباع محمد أوف بعهدكم في رفع الإصر والأغلال التي في أعناقكم \"\nوقيل: أوفوا بعهدي في ترك الكبائر أوف بعهدكم في غفران الصغائر، وقيل: أوفوا بعهدي في أداء الفرائض أوف بعهدكم في الإثابة عليها)، وقيل: (أوفوا بعهدي في الاهتداء إلى طريق الاستقامة أوف بعهدكم في الزيادة في الاهتداء وإيتاء الاتقاء - إشارة إلى ما قال:\n﴿وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ﴾⟪47:17⟫، وهذه الأوقايل اختلفت إما بحسب اختلاف النظرات، أو بحسب اختلاف العبارات، وفيما بين من الأصل معرفة نظر الكل، وإن عامة أقوالهم لا\n⟦1:169⟧\nتخرج عن الصواب - إن شاء الله -.\nوقال تعالى لهذه الأمة: ﴿فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ﴾⟪2:152⟫، فقال بعض المحققين في اعتبار الآيتين دلالة على تشريف هذه الأمة في أنه لما خصهم بفضل فهم وعقل، أمرهم بذكره بلا واسطة، وأمر بني إسرائيل أن يجعلوا ذكر الآية وصلة إلى ذكره، وذلك فصل قد أحكم في كتاب: (شرف التصوف )، وقوله: \" فارهبون \"، تقديره: ارهبوني، فحذف الياء لدلالة الكثرة عليه، وكون الفواصل كالقوافي، وفائدة تكرير الضمير توكيد للحث على رهبته، وأنها لا يجوز أن تكون إلا منه تعالى دون غيره، ومثله في تذكيرهم نعمة الله تعالى ما حكاه تعالى عن موسى قال لهم: ﴿ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ﴾⟪5:20⟫"}, {"a": [41], "v": 1, "p": 169, "ev": 1, "ep": 171, "sid": 170, "t": "قوله - عز وجل -\n﴿وَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقٗا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗا وَإِيَّٰيَ فَٱتَّقُونِ﴾⟪2:41⟫\n\" الآية: (41) - سورة البقرة \".\nقد تقدم أن الإيمان مقتض للعلم اليقيني، ففي ضمن قوله تعالى: ﴿وَءَامِنُواْ بِمَآ أَنزَلۡتُ﴾⟪2:41⟫ حث على استفادة العلم، إذ لا يحصل الإيمان الحقيقي من دونه، ونبه بقوله تعالى: ﴿مُصَدِّقٗا لِّمَا مَعَكُمۡ﴾⟪2:41⟫ أن لا منافاة بين ما أتى به الأنبياء من أصول العبادات، وأنهم كنفس واحدة من حيث يتساوى دعاؤهم إلى التوحيد والأركان الثلاث من الشرائع التي هي العبادات الخمس وأحكام الحلال والحرام والمزاجر، وإنما الاختلاف بينهم في جزئيات الأحكام وفروعها كيفما تقتضيه مصلحة قوم وزمان، فكل مصدق للآخر فيما أتى به من أن كليات شرائعهم متساوية، وأن فروعها حق بحسب الإضافة إلى زمان كل واحد منهم، وأمته حتى لو كان أحدهم في زمن الآخر لم ير المصلحة إلا فيما أتى به الآخر، ولذلك قال عليه السلام: \" لو نشر موسى بن عمران لما وسعه إلا اتباعي \"، وقوله: ﴿وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ﴾⟪2:41⟫ أي لا تكونوا أئمة في الكفر، فيقتدي بكم تباعكم، فتكونوا لأوزاركم وأوزارهم، كما قال تعالى\n⟦1:170⟧\n﴿لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ﴾⟪16:25⟫ وذلك إشارة إلى ما قاله عليه السلام \" من سن سنة حسنة فله أجرها وأجر من عمل بها، من سن سنة سيئة فله وزرها ووزر من عمل بها \" وقيل: معنى \" أول \" المتقدم بالشرف كقولهم: \" حاتم أول الأسخياء، وما رد أول اللئام، والمعنى: لا تكونوا أرفع كافر منزلة في الكفر، وذاك أن محمدا: عليه السلام - لما كان أخر الأنبياء، وكان متمما لشرائع من تقدمه، كما روي عنه - عليه السلام أنه قال: \" إنما مثلي ومثل الأنبياء كرجل بني بنيايا وأكملها، وترك موضع لبنة، فأنا كنت موضع اللبنة \"، فصار الكافر به كالكافر بجميعهم، فإن من شرط من الإيمان بهم أن يضامه الإيمان به، وإلا لم يعتد بإيمانه بهم، والهاء في قوله تعالى: \" به \" ضمير \" ما أونزلت \"، وقيل: هو ضمير \" ما معكم \"،\nإن قيل: لم قال: \" ولا تكونوا أول كافر به \" وأنت لا تقول \" كونوا أول رجل \" وإنما تقول \" رجال \"؟ قيل: إن ذلك معناه: \" أول كافر أو خرب مما لفظه المفرد، ومعناه الجمع على ذلك قول الشاعر:\nفإذا هم طمعوا فالأم طاعم\n....\nوإذا هم جاعوا فشر جياع\nوقد أجاز بعضهم إخوتك أول رجل، أي أول الرجال إذا كانوا رجلا رجلا، والقليل والكثير من الأسماء المتضايقة، ويعتبران بالغير، وليس استعمال القلة في قوله: ﴿وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗا﴾⟪2:41⟫ لأجل اعتبار ثمنين من أعراض الدنيا، كما تصوره بعض الناس فاعترض على الآية: وقال: ذلك\n⟦1:171⟧\nيقتضي جواز اشتراء الثمن الكثير بآيات الله، بل جعل الاعتبار ههنا بمنافع الدنيا والآخرة، وقد علمنا أن منفعة الدنيا طفيفة، إذا اعتبرت بمنفعة الآخرة، وإذا كان كذلك، فمن اشترى بآيات الله منافع الدنيا، وترك منافع الآخرة، فقد خسر خسرانا مبينا، كما حكي عن \" المنصور \" لما حضرته الوفاة: قال: أف لنا، بعنا نعيم الآخرة بنومة، وقال الشاعر:\nوإن امرءا يبتاع دنيا بدينه ...\nلمنقلب منها بصفقة خاسر\nوعلى هذا قوله تعالى:\n﴿فَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ﴾⟪2:79⟫\nالآية: (79) - سورة البقرة.\nوإنما ذكر في الآية الأولى.\n(فارهبون) وفي الآية الآخرى (فاتقون)، لأن الرهبة دون التقوى، فحينما خاطب الكافة عالمهم ومقلدهم، وحثهم على ذكر نعمة التي يشركون فيها، أمرهم بالرهبة التي هي مبادئ التقوى، وحينما خاطب العلماء منهم، وحثهم على مراعاة آياته والتنبه لما يأتي به أولوا العزم من الرسل، أمرهم بالتوقى التي هي منتهى الطاعة ..."}, {"a": [42], "v": 1, "p": 171, "ev": 1, "ep": 173, "sid": 172, "t": "قوله - عز وجل -\n﴿وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ﴾⟪2:42⟫ الآية (42) - سورة البقرة.\nاللبس والستر، والتغطية، والتعمية، والتموية، والكتمان، والإخفاء يتقارب، فالستر أعم الألفاظ، لأنه يقال في المحسوس والمعقول \" سترت كذا بثوبي \"، وسترته في نفسي، والتغطية في الأعيان فقط، واللبس أصله في الثوب، ثم يقال في المعنى أيضا، وذلك أن يخلط حق بباطل، وصدق بكذب، والتعمية: ما جعل الإنسان عن إدراكه كالأعمى، والتموية: ما جعل على وجهه مواهة، والكتمان: يقال في الحديث ونحوه، وقوله: ﴿وَتَكۡتُمُواْ ٱلۡحَقَّ﴾⟪2:42⟫ أخص من قوله: ﴿تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ﴾⟪2:42⟫، لأن اللبس هو الخلط بغيره، والكتمان إخفاؤه جملة، والأجود أن يكون قوله: ﴿وَتَكۡتُمُواْ﴾⟪2:42⟫ جوابا بالواو منصوبا.\nوإن صح أن يكون عطفا مجزما، فيكون أمرا بخصوص بعد عموم، وقراءة أبي:\n⟦1:172⟧\n(ولا تكونوا أول كافر به وتشتروا بآياتي ثمنا قليلا وتكتموت الحق)، ونحو ذلك في احتمال الجواب والعطف ..\nقوله: ﴿وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ﴾⟪2:188⟫، وقوله: ﴿وَأَنتُمۡ تَعۡلَمُونَ﴾⟪2:42⟫ تعظيم لارتكاب الذنب، فإنه مع العلم بقبحة لأعظم عقوبة، ولهذا قال بعض الحكماء:\n(لأن أدع الحق جهلا به، أحب إلى من أن أدعه زهدا فيه، ولأن أترك جميع الخير جهلا به أحب إلى من أفعل أقل الشر، بعد المعرفة بقبحه).\nوقد تقدم الكلام في الحق، فأما الباطل: فالإثبات له عند الفحص عنه، والحق يناقضه، وذلك عام في الاعتقاد والمقال والفعال.\nولذلك قال الشاعر:\nلقد نظقت بطلا على الأقارع.\nفاستعمله في القول، وفي الآية حث على تجنب الشر والنهي عن كل تلبيس وتمويه وإن كانت الآية واردة فيمن آمنوا ببعض الكتاب، وكفروا بالبعض، وجحدوا صفة النبي - صلى الله عليه وسلم - وقول ابن عباس - رضي الله عنهما: [لا تخطلوا الصدق بالكذب وقول بن زيد] لا تخلطوا الحق الذي هو التوارة بالباطل الذي كتبتموه بأيديكم، فإشارة إلى بعض ما يقتضيه عموم الآية.\n⟦1:173⟧"}, {"a": [43], "v": 1, "p": 173, "ev": 1, "ep": 173, "sid": 174, "t": "قوله تعالى:\n﴿وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱرۡكَعُواْ مَعَ ٱلرَّٰكِعِينَ﴾⟪2:43⟫ \" الآية (43) - سورة البقرة.\nقد تقدم الكلام في إقامة الصلاة، فأما الزكاة، فأصلها من: \" زكا الزرع، فهي بالنظر، العامي: تثمير المال باستجلاب تركه الله - عز وجل -، وبالنظر الخاصي: تتميز النفس، وهو تطهيرها بإخراج الحقوق من المال.\nوالتزكية قد تقال في المقال، نحو: \" زكيت فلانا، وعلى ذلك قوله: ﴿فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ﴾⟪53:32⟫، وذلك نهي عن الثناء على النفس، فإنه من المستقبح بالعقل والششرع، ولذلك قيل لحكيم:\nما الذي لا يجسن وإن كان حقا؟ فقال: مدح الرجل نفسه.\nوقد تقال التزكية في الفعال، وهي ما يقتضي تظهير النفس المدعو إليه بقوله تعالى: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ﴾⟪2:222⟫\nوقلما حث الله تعالى على إقامة الصلاة، أو مدح بها، إلا قرن بها إيتاء الزكاة، فبهما يتم الإيمان، وعليها دل قوله تعالى:\n﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫، وقوله: ﴿ٱرۡكَعُواْ﴾ حث على الخضوع وتذرع الخشوع، ويصح أن يكون مع ذلك - حثا على مراعاة الجماعات في الصوات والاجتماع مع المؤمنين في كل مأمور به نحو قوله تعالى:\n﴿وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ﴾⟪3:103⟫، ولذلك قال: ﴿مَعَ ٱلرَّٰكِعِينَ﴾⟪2:43⟫"}, {"a": [44], "v": 1, "p": 174, "ev": 1, "ep": 177, "sid": 175, "t": "﴿أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ﴾⟪2:44⟫\nالآية (44) - سورة البقرة.\nالبر: التوسع في أفعال الخير، بدلالة ما قاله - عليه السلام - وقد سأله أبو ذر عن البر، فتلا عليه قوله تعالى: ﴿لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ﴾⟪2:177⟫ الآية إلى قوله: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ﴾⟪2:177⟫.\nفذكر جملة أفعال الخير، فرائضها، ونوافلها، ومكارم الأخلاق كلها.\nفالبر في ثلاث:\nبر في معاملة الله تعالى وعبادته، وبر في معاملة الأقارب ومراعاة حقوقهم، وبر في معاملة الأجانب وإنصافهم.\nواشتقاقه من البر هو الفضاء والسعة، ولهذا وصف المؤمن بسعة الصدر، والكافر بضده، نحو قوله تعالى:\n﴿فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا﴾⟪6:125⟫ ..\nالآية، فسمي برا ...\nوقد وصف الله تعالى بالبر كما وصف به العبد، يقال \" بر العبد ربه \"، أي أطاعه، على ذلك قول الشاعر:\nيبرك الناس ويفخرونكا\nوالله - عز وجل - بر عبده، أي وسع عليه إحسانا، ويقال: أبر فلان على فلان أي تقدمه ببر،\n⟦1:175⟧\nأي سعة من المكان، وعلى هذا قالوا: بينهما بون، وقال الشاعر:\nفثم الفتى كل الفتى كان بينه ...\nوبين المراجي نفنف متباعد\nوالنسيان: زوال الشيء عن الحفظ، فهو ضربان:\nانفعال بغير فعل من صاحبه، وهو المعفو عنه بقوله - عليه السلام - \" رفع عن أمتي الخطأ والنسيان \".\nوأنه قال بفعل من صاحبه، وهو أ، يترك مراعاة المحفوظ حتى يذهب عنه، وهو المذموم بقوله تعالى:\n﴿كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ﴾⟪20:126⟫، وقال عليه السلام:\n\" من حفظ القرآن، ثم نسيه، لقي الله وهو أجذم \"، ولما ورد هذا الخبر عن النبي - عليه السلام - كره ابن مسعود - رضي الله عنه أن يقول القائل: \" نسيت آية كيت وكيت \"، والق:\nلتقل: \" أنسيت، ومن جعل الإنسان من ذلك، فأصله عنده: \" أنسيان \"، بدلالة: \" أنيسيان \" في تصغيره، ومعنى تلاه: تبعه، والتلاوة في القرآن إتباع اللفظ اللفظ، أة: إتباع اللفظ بتدبر المعنى، وهو المراد بقوله: ﴿يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ﴾⟪2:121⟫، والعقل: أصله المنع الشديد، ومنه: عقل البعير \"، \" والعاقول \": الدواء، يمسك البطن، والعقلية للنفس الممنوع عن الإخراج، والمعقلة، والعقال، واعتقل لسانه.\nوقد ذكر الله تعالى \" العقل \" بأربعو أسماء: \" العقل، والنهي، والحجر، واللب \" وذلك بأنظار مختلفة -، فأكثرها ذكر العقل، وذلك لعقله عما يقبح وعلى ما يحسن، والنهي: لكونه ناهيا عن القبائح، والحجر: لجعل صاحبه في حجر عما لا يحسن، واللب: لكون ذلك الجزء من الإنسان، بالإضافة إلى\n⟦1:176⟧\nسائر أجزائه، كلب الشيء إلى أجزائه، وهو أشرف أسمائه، وقد ذمهم الله تعالى في هذه الآية بغاية ما يذم به المتصدي للوعظ بغير الحق، وذاك أن الواعظ من الموعوظ يجري مجرى المظلة من الظل، والطابع والمطبوع، ومحال أن تعوج المظلة، ويستوي ظلها، أو يمكن للطابع أن يوجد في مطبوعة أحسن ما في طبعه.\nولهذا قيل: \" كفى بالمرء تهزيا أن يعظ غيره وينسى نفسه، ولأن المدعي لمصلحة هو يتجنبها إما كاذب في دعواه، و‘ما خبيث النفس، وكلاهما لا يقبل قوله، فإذا \" حق الإنسان أن يبدأ بنفسه فيما يعظ به غيره، حتى يكون واعظا بفعله كوعظة بقوله.\nوروي أن رجلا أتى ابن عباس [رضي الله تعالى عنهما] فقال: \" إني أريد أن آمر بالمعروف وأنهى عن المنكر، فقال: إن لم تخش أن تفتضح بثلاث آيات من كتاب الله تعالى فافعل.\nقوله تعالى: ﴿أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ﴾⟪2:44⟫، وقوله تعالى: ﴿لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ﴾⟪61:2⟫، وقول شعيب: ﴿وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ﴾⟪11:88⟫، وقد اتبع الله ذمهم بحكمين حقق غيهم أحدهما، قوله: {وانتم تتلون) أي: تتدبرون التوراة، والثاني: قوله: (أفلا تعلقون) - تنبيها - أن الجامع للعقل ومتبع الكتاب ليس من حقه أن يأمر الغير بما لا يفعله، فذلك منبئ عن الجهل، فصارت الآية بما عقبت أبلغ من معنى قول الشاعر:\nلاتنه عن خلق وتأتي بمثله\n....\nعار عليك إذا فعلت عظيم\nوقوله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ﴾⟪5:105⟫ مثل هذه الآية في حث الإنسان على (العناية بالنفس) قبل العناية بغيره، لا نهيا عن الوعظ كما تصوره بعض الناس، حتى قال هذه الآية منسوخة ..\n⟦1:177⟧"}, {"a": [45], "v": 1, "p": 177, "ev": 1, "ep": 178, "sid": 178, "t": "قوله - عز وجل -:\n﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ﴾⟪2:45⟫: الآية (45) - سورة البقرة.\nأصل الصبر: الإمساك في ضيق، ومنه: دابة مصبورة، والصبرة من الطعام للجمعة منه، وفي التعارف: إمساك النفس على ما يقتضيه العقل وعما يقتضيه، وذلك ضربان: صبر عن المشتهى، وهو العفة، وصبر على المكروه وهو الشجاعة، وقيل الصبر: الصوم، لقوله عليه السلام: (صيام شهر الصبر وثلاثة أيام من كل شهر يذهب كثيرا من وحر الصدر)، وتسميته بالصبر، لكونه بعضه، إذ هو إمساك الشهوة، ولهذا قال عليه السلام:\n\" الصوم نصف الصبر \"، والصلاة أرفع منزلة من الصبر، لأنها تجمع ضروبا من الصبر، إذ هي حبس الحواس على العبادة، وحبس الخواطر والإفكار على الطاعة، ولهذا قال:\n﴿وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ﴾⟪2:45⟫، وخصها برد الضمير إليها دون الصبر، وأما الصلاة التي تخفف على غير الخاشع، فإنها مسماة باسمها، وليس هي في حكمها، بدلالة قوله تعالى: ﴿إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ﴾⟪29:45⟫، ومثلها، وقل ما ترى صلاة غير الخاشع تنهاه عن الفحشاء والمنكر، ومثلها في رد الضمير على أحد المذكورين لاختصاص العناية به، قوله: ﴿وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا﴾⟪62:11⟫، فأعيد الضمير إلى التجارة - لما كانت سبب انفضاض الذين نزلت الآية فيهم، ولأنه قد تشغل التجارة عن العبادة من لا تشغله اللهو، وعلى ذلك قوله: ﴿وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ﴾⟪9:34⟫ لما كان حبس الفضة عن الناس أعظم ضررا، إذ كانت\n⟦1:178⟧\nالحاجة إليها أمس، ومنعها للمضرة أجلب، [خصا بالضمير]، وقوله: (كبيرة) اي: كبيرة القدر، أو ثقيلة على النفس، بالإضافة إلى غيرها من العبادات وزائدة عليها، فإنها لا تصح إلا ببذل مال ما جار مجرى الزكاة فيما يستر به العورة، ويطهر به البدن، وإمتساك في مكان مخصوص يجري مجرى الاعتكاف، وتوجه إلى الكعبة يجري مجرى الحج، وذكر لله ولرسوله يجري مجرى إظهار الشاهدتين للإيمان، ومجاهدة في مدافعة الشيطان سارية مجرى الجهاد، ومساندة عن الأطيبين جار مجرى العموم، وفيها ما ليس في العبادات الآخر من وجوب القراءة، وإظهار الخشوع، والركوع والسجود، وغير ذلك، ولهذا عظم النبي - صلى الله عليه وسلم - أمرها، فكان آخر ما أوصى به عند وفاته: \" الصلاة، وما ملكت إيمانكم \"، وجعل بقولها وما يفيض بها لسانه."}, {"a": [46], "v": 1, "p": 178, "ev": 1, "ep": 179, "sid": 179, "t": "قوله - عز وجل -:\n﴿ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ﴾⟪2:46⟫ ...\nالآية (46) سورة البقرة.\nقد تقدم الكلام في الظن، وأنه أعم ألفاظ الشك واليقين، وأنه اسم لما تحصل عن أمارة متى قويت أدت إلى العلم، ومتى ضعفت حدا لم يتجاوز حد الوهم، [وأنه متى قوي استعمل معه أن المشدةة، و \" أن \" المخففة منها]، ومتى ضعفت استعمل معه \" أن \" المختصة بالمعدومين من الفعل نجو \" ظننت أن خرج، وأن يخرج \" فالظن إذا كان بالمعنى الأول فمحمود، وإذا كانت بالمعنى الثاني: فمذموم، والآية من المعنى الأول والمعنى الثاني كقوله: ﴿وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ﴾⟪2:78⟫، وقوله: ﴿وَإِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـٔٗا﴾⟪53:28⟫، وعنى بلقاء الله \" الموت \" وبالرجوع إليه \" الثواب والعقاب \"، وتخصيص ذكر الظن ها هنا إعلام بأنهم في كل حال لا يأمنون الموت، ولو كان بدله العلم، [لم يصح على الوجه] الذي يصح فيه الظن، لأنك تقول: \" أظن أني أموت في كل حال، وأما قوله ﴿أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ﴾⟪83:4⟫، فهو نهاية في الذم، ومعناه: ألا تحصل لهم أمارة تنبههم على التفكر في ذلك - تنبيها\n⟦1:179⟧\nأن هذا لا محالة مما تبين أمارته للإنسان إذا تأمل، أدني تأمل، وخاطب بالآيات عماء بني إسرائيل الآميرن غيرهم بالبر، الناسين أنفسهم بأن استعينوا في مدافعه هذه الحال بالصبر والتوصل به إلى الصلاة، فبها يصير الإنسان خاشغا ملتزما للحق ممن ظهر منه."}, {"a": [47], "v": 1, "p": 179, "ev": 1, "ep": 181, "sid": 180, "t": "وقوله - عز وجل -:\n﴿يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ﴾⟪2:47⟫\nالآية (47) سورة البقرة.\nالفضل: كالزيادة، إلا أنه أخص منها، وهو من الأسماء المتضايقة، كالكثير، والقليل، والكبير، والصغير، ويستعمل على اعتبارين: أحدهما: اعتبارا بالطرف الذي هو النقص، وذلك يستعمل على سبيل المدح، والثاني: اعتبارا بالوسط الذي هو العدل والسواء، ويستعمل ذلك على وجهين: أحدهما: الزائد على العدالة على سبيل الاستظهار، وهو السماحة والإسماح ببعض ما لا يجب عليه، أو بترك بعض ما لا يجب له، وذلك هو المعنى بالإحسان: في قوله:\n﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ﴾⟪16:90⟫، وبالزيادة في قوله: ﴿لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ﴾⟪10:26⟫، وإياه عنى بقوله: ﴿وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ﴾⟪2:237⟫، والثاني: الإفراط الجاري في الذم مجرى التفريط، كالإسراف والتبذير المنهي عنه بقوله: ﴿وَلَا تُسۡرِفُوٓاْۚ﴾، وقوله: ﴿وَلَا تُبَذِّرۡ تَبۡذِيرًا﴾⟪17:26⟫، والمعبر عنه بقول العامة: \" الزيادى على الكفاية نقصان \"، وأكثر ما يعبر عنه بالفضلة والفضالة فالزيادة على الاعتبار الأول فضيلة، وهو استظهار في العدالة، وعلى الاعتبار الثاني رذيلة، وهو ترك العدالة، والتفضيل: يستعمل على وجهين: إما بمنحة خص المفضل بها نحو قوله: ﴿وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا﴾⟪17:70⟫، فإن ذلك أمور خص بها بنو آدم ابتداء، وأما الحكم للمفضل بالفضل الحاصل منه، نحو قوله: ﴿وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا﴾⟪4:95⟫، فالأول: يجب على العبد به الشكر، إذا هو مدح له، نوليس له به حمد، والثاني: يجب له به حمد، ويستحق به الثواب، وأما العالمون: فقد تقدم الكلام فيه، وأنه تارة يقال لجميع ما أوجده الله تعالى من الفلك، وما يحويه عالم بلفظ الإفراد، وتارة\n⟦1:180⟧\nيقال لكل جنس نوع من الموجودات عالم وتارة يقال لأهل كل زمان عالم وتارة يقال لكل إنسان في نفسه عالم، وذلك يقال على وجهين: أحدهما: إن الإنسان الواحد هم كالعالم في تخصيصه بمثال كل ما هو موجود في العلم والثاني: يقال ذلك للفاضل الكامل من الرجال، وبهذا النظر قال الشاعر:\nفواحدهم في الورى عالم.\nإن قيل كيف قال: فضلتكم على العالمين وقد قال تعالى لهذه الأمة: ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾⟪3:110⟫ الجواب: أن التفضيل الذي يكره الله تعالى هو الفضيلة التي خص بها نبو آدم، المعنية بقوله: ﴿وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ﴾⟪17:70⟫ الآية، وبنو إسرائيل وإن كان قد شاركهم غيرهم في هذه النعمة، فإنهم لما نسوا نعم الله تعالى خصوا بالنداء لتذكيرهم، كقولك: \" يا فلان نسيت نعمة الله عليك \"، وقد تقدم أنه ربما يخص بالمخاطبة لتذكيرهم بعض المعنيين بالحكم، لأنه أرفعهم منزلة، أو لأن العناية ما أعطوا من المن والسلوى وإظلالهم بالغمام، والحجر الذي تفجر منه الأنهار، وغير ذلك: وقيل: إنه جعل كل فرقة أو كل نفس في زمانهم عالما، وذكر أنه فضلهم على غيرهم ممن في زمانهم، وقيل: إن ذلك بمارشحهم له من الإيمان بالله ورسوله والأعمال الصالحة، فإن من فعل ذلك كان هو المفضل على العالمين، كقوله: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ﴾⟪98:7⟫\nإن قيل: كيف قال ذلك وهذه النعم كانت على أسلافهم؟ قيل: قد قال بعضهم: لما ذكر الله تعالى ذلك في التوراة على سبيل الخطاب، أعاد اللفظ على الحكاية، وقيل: \" النعمة على الإنسان ضربان \": نعمة تصل إليه من المنعم بلا واسطة، ونعمة تصل إليه من المنعم بواسطة، أو بوسائط وذلك كتسخير الله من يزرع لنفسه زرعا يصل إلينا نفعه على بعض الوجوه، فهذا الزارع منعم علينا، وعلى هذا قيل: إن الله تعالى منعم على كل واحد منا بأكثر ما يتعاطاه الناس من أعمالهم من المهن والصنائع المرفقة لأنفسهم، ونحو هذه الآية قول الله - عز وجل - ﴿ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ﴾⟪5:20⟫ وأعاده قوله:\n⟦1:181⟧\n﴿يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ﴾⟪2:47⟫، فلأن الأول: حث على استيقاء نعمته بالوفاء بعهده، والثاني: لتبينها بتفضيلهم على العالمين."}, {"a": [48], "v": 1, "p": 181, "ev": 1, "ep": 183, "sid": 182, "t": "قوله - عز وجل -\n﴿وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ وَلَا هُمۡ يُنصَرُونَ﴾⟪2:48⟫ ...\nالآية (48) سورة البقرة.\nالجزاء والمكافأة، والمقابلة متقاربة، لكن الجزاء أعمها، لأن المكافأة: يعتبر فيها المماثلة والمقابلة: يراعى فيها المجازاة، والجزاء لا يراعى فيه شيء من ذلك، ويقال: جزاه \" بلا همزة \"، يجزيه، أو \" أجزاه \" بالهمزة، ففي الجزاء معنى العناء، والقبول تناول المقبل، ومنه القابل: المتناول الدلو، وأصل ذلك من قبل وقبل.\nفقبل يستعمل في المتقدم المنفصل، ويضاده بعد، وقبل: في المتصل، ويضاده: دبر، وقد جعل كناية عن السوءتين، ويقابل القبول الرد.\nوالشفاعة: جعل الفرد شفعا يقال: شفعت له، أي صرت شفعا له بانضمامي إليه، وعبر عمن انصم إلى غيره في طلب ما \" شافع \"، وعلى ذلك قول الشاعر:\nله من عدو مثل ذلك شافع.\nومنه الشفعة، وأصلها ضم ملك إلى ملكه، وشفعه به، والعدل: التسوية، يقال: عدلته، وانعدل، وعدلته، فاعتدل، وعدل الشيء مساويه بلا إفراط ولا تفريط، وأكثر ما يقال في المساوي من حيث الحكم نحو قوله - عز وجل -:\n﴿أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا﴾⟪5:95⟫، والعدل: يقال في المساوي، في الكمية في الوزن والكيل، وقيل الفداء: العدل إذا اعتبر فيه معنى المساواة، وقولهم: \" لا يقبل منه صرف ولا عدل \".\n⟦1:182⟧\nوتفسيرهم بأن العدل: الفريضة، والصرف: النافلة، فمن حيث أن العدل هو المساواة، وتعاطيه واجب، والصرف: الزيادة الحاصلة عن التصرف، وتعاطيه تبرع وهما كالعدل والإحسان.\nوالنصرة أخص من المعونة، فإنها تختص بدفع الشر والظلم، وقيل أرض منصورة: إذا أتاها المطر بعد طول مدة، والقصد بالآية التقوى من يوم لا يكفي أحد أحدا.\nوقد أعاد تعالى هذا المعنى في غير موضع، كقوله تعالى: ﴿يَوۡمَ لَا يُغۡنِي مَوۡلًى عَن مَّوۡلٗى شَيۡـٔٗا﴾⟪44:41⟫\nوقوله: ﴿يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ ۝ وَأُمِّهِۦ وَأَبِيهِ﴾⟪80:34-35⟫، وقوله: ﴿وَٱخۡشَوۡاْ يَوۡمٗا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ﴾⟪31:33⟫، تنبيها أن لكل واحد ما يستصحبه من الإيمان والأعمال الصالحة: كما قال: ﴿وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ﴾⟪53:39⟫،\nإن قيل: كيف قال ذلك، وقد أثبتت الشفاعة في غير آية، قيل: هذا رد على اليهود فيما ادعوه حيث قالوا: \" نحن أبناء الأنبياء وهم يشفعون لنا وإن ارتكبنا (ما ارتكبنا)، فنبه على أنه ليس لهم شفاعة كما قال: ﴿يَوۡمَئِذٖ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلٗا﴾⟪20:109⟫، وقوله: ﴿وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ﴾⟪21:28⟫، والضمير من قوله - عز وجل - ﴿وَلَا يُقۡبَلُ مِنۡهَا﴾⟪2:48⟫ راجع إلى النفس الأولى وقيل أنه راجع إلى الثانية، وفي قوله: ﴿وَلَا يُؤۡخَذُ مِنۡهَا﴾⟪2:48⟫ راجع إلى الثانية لا محالة، وقوله: ﴿وَلَا هُمۡ يُنصَرُونَ﴾⟪2:48⟫، أي ليس لهم من ينتصر من الله تعالى بأن يمنعهم من عذابه إشارة إلى قوله تبارك وتعالى: ﴿وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ ۝ مَا لَكُمۡ لَا تَنَاصَرُونَ﴾⟪37:24-25⟫، وقوله: ﴿وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي﴾⟪2:48⟫، قيل: معناه: ﴿لَّا تَجۡزِي﴾⟪2:48⟫ فيه، فحذف، وهو قول الكسائي، وقال البصريون، وصل الفعل إليه.\nفنصبه نحو قول الشاعر:\nويوم شهدناه سليما وعامرا\nثم حذف الهاء كحذفه من \" الذي ضربت \".\nوحقيقة الخلاف أن ما يقدر الكسائي حذفه بدفعه يقدره البصريون بدفعتين، ولا خلاف أن الأصل كان في ذلك فيه وأنه لا يطرد في كل مكان حذف الجار مع المجرور.\n⟦1:183⟧"}, {"a": [49], "v": 1, "p": 183, "ev": 1, "ep": 187, "sid": 184, "t": "قوله - عز وجل -:\n﴿وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ﴾⟪2:49⟫ الآية (49) سورة البقرة.\nأصل النجاء: طلب الخلاص، ويقال لمن عدا نجا، لكون العدو أحد أسباب التخلص، فإن الله تعالى جعل للحيوانات قوتين تزيل بهما الأذى، قوة بها تهرب مما يؤذيها، وقوة بها تدفع ما يؤذيها، فمن الحيوانات ما يختص بأحديهما، ومنها ما جعلتا جميعا به، فإذا: العدو أحد أسباب الخلاص، فصح أن يعبر عنه به، وقيل: \" نجا فلان)، إذا ألقة ثوبه وذلك استعارة له، كما استعير إلقاء الثوب للعدو في نحو قولهم: \" القى بزه \" وخلع ثوبه، وعلى ذلك قوله :\nألقيت ليلة خبث الرهط أرواقي\nوسميت الربوة \" نجوا \" اعتبارا بأنه منجي من السيل وكثير من الآفات التي تكون في الوهاد، وكنى عن العذرة الملقاة بالنجو إما اعتبارا بأنه خلاص من الأذى، أو كناية عنه بالنجو، كما كنى عنه بالغائط ولما اعتقد في السر أنه خلاص من الوشاة والعداة سمي بنجوى، وبهذا النظر قال الشاعر:\nونجعل نجوانا نجاة من العدا ...\nوالآل: قيل هو مقلوب عن الأهل، كالماء عن الموه، ويصغر على أهيل، كما أن الماء مصغر على مويه، إلا أنه خص بالإضافة إلى أعلام الناطقين دون النكرات ودون الأزمنة والأمكنة، يقال: \" آل فلان \"، ولا يقال: آل مكة، وزمان كذا: هو اسم للشخص، ويصغر على \" أوائل \"، وهو قول الكسائي، ويستعمل فيمن اختص بالإنسان اختصاص ذاته به إما بقرابته قربته، أو بموالاة دينه، أو كالدينية، فقد أجرى الموالاة الدينية مجرى القرابة واللحمة حتى قال تعالى: ﴿وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ﴾⟪5:51⟫،\n⟦1:184⟧\nوقال: ﴿فَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ﴾⟪14:36⟫، وقال في نوح وابنه: ﴿إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ﴾⟪11:46⟫، والاختصاص المذكور قال تعالى:\n﴿إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ ۝ ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ﴾⟪3:33-34⟫، ولاختصاص الآل بما قلنا، قال تعالى: ﴿أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ﴾⟪40:46⟫ وقال هذا القائل: أهل الدين من النبي - عليه السلام - ضربان: ضرب يتخصص منه بالعلم المتقن والعمل المحكم، فيقال لهم: آل النبي، وضرب يتخصص منه بالعمل على سبيل التقليد دون العلم المتقن، ويقال لهم أمة، فكل آل النبي أمته، وليس كل أمته آله، وقيل لجعفر بن محمد: إن ناسا يقولون: المسلمون كلهم آل النبي، فقال: كذبوا وصدقوا، قيل: فما معنى كذبوا وصدقوا؟ قال: كذبوا: أن الناي على ما هو عليه من التقصير في دينهم هم آل محمد، وصدقوا: أنهم آله إذا قاموا بشريطه شريعته، فمن ضيع الشريطة، فليس منه وإن قرب نسبه، ومن حافظ على شريطته فهو منه وإن بعد نسبه، والسوم: أصله الذهاب في إبتغاء الشيء، فهو لفظ لمعنى مركب الذهاب والابتغاء فإنه جرى مجرى الذهاب ، فقيل: \" سام الإبل \"، فهي سائمة إذا ذهبت في المرعى، و \" سمته كذا \"، كقولك نعيته كذا، ومنه السوم في البيع، فعدى تعديته والسوء: يتناول كل ما يسوء الإنسان من آفة وداء، ويقال: السوء والسوى، أي: نحو الحسن والحسنى، وعلى سبيل كراعية ذكر الفرج والنظر إليه، كنى عنه بالسوءة، وكذا كنى عن البرص بها، وسوء العذاب: أي شدة العذاب، والذبح أصله شق الأوداج، وقيل: ذبحت الفارة النافجة على الاستعارة، لما شبه ذلك الوعاء بفارة فسمي بها، والذباحة: كأنه يذبح بشدته وكونه في المذبح، وخصت سنا يكثر في الأدواء، نحو: خراجة تخصيص التذبيح دون الذبح تنبيها على كثرة ذلك منهم، والاستحياء: كالاستبقاء، وهو تحري طلب الحياة فيهن، وقيل: معناه: يبتغون ما في أرحام النساء مشتقا من\n⟦1:185⟧\nالحي، أي الفرج، والبلاء أصله من قولهم: بلى الثوب بلى، وبلاء، وقيل \" بلوت فلان \" أي أخبرته كأني أخلقته من كثرة اختباري له، ولهذا قيل: \" لبست فلانا \"، أي: خبرته، وسمي الغم بلاء من حيث أنه يبلى الجسم، وسمي التكليف بلاء من أوجه، الأول: أن التكاليف كلها مشاق على الأبدان، فصارت من هذا الوجة بلاء، والثاني: أن التكاليف اختبارات، وكذلك قال: ﴿وَلَنَبۡلُوَنَّكُم﴾، قال ﴿لِّيَبۡلُوَكُمۡ﴾، ونحو ذلك، والثالث: أنه لما كان اختبار الله تعالى لعباد تارة بالمسار ليشكروا، وتارة بالمضار ليصبروا، صارت المنحة والمحنة جيمعا بلاء، فالمحنة: مقتضية للصبر والمنحة: مقتضية للشكر، وكأن القيام بحقوق الصبر أيسر من القيام بحقوق الشكر لما بيناه في كتاب: (شرف التصوف)، فصارت المنحة أعظم البلاء، وبهذا النظر قال أمير المؤمنين علي - رضي الله عنه وكره الله وجهه: \" من وسع عليه في دنياه، ولم يعلم أنه مكر به، فهو مخذوغ عن عقله \" والرابع: أنه رب منحة تعقب محنة، ومحنة تقضي إلى منحة، ولهذا قيل: \" رب مغبوظ بنعمة هي داؤه، ومرحوم لشدة هي شفاؤه \"، فإذا: من النعمة ما هو نقمة \" ولكون البلاء متناولا للأمرين، قال تعالى، ﴿وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ﴾⟪7:168⟫، وقال: ﴿وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ﴾⟪21:35⟫، وقالوا \" في الخير والشر معا: بلاه \" فإذا أفردا قالوا [في الخير: ابلاؤه ، وفي الشر بلاه] وقال تعالى: ﴿وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ﴾⟪8:17⟫، وأما قول الشاعر:\nجزى الله بالإحسان ما فعلابكم ...\nوأبلاهما خير البلاء الذي يبلو\n⟦1:186⟧\nفمعناه: أعطاهما الله خيرا فيما يمنحهما به، وجعل لهما بدل المكروه محبوبا، فقوله: ﴿وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ﴾⟪2:49⟫ راجع إلى الأمرين إلى المنحة التي هي الإنجاء من آل فرعون المقتضية للشكر، وإلى المحنة التي هي ذبحهم واستحياؤهم للنساء المقتضية للصبر، وعلى ذلك قوله تعالى: ﴿وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمۡ يَرۡجِعُونَ﴾⟪7:168⟫ فإذا صح ذلك، فقول مجاهد وابن جريح: أنه أراد في إنجائكم منهم نعمة، نظر منها إلى مبدأ الآية، وهو قوله: ﴿أَنجَيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ﴾، وقول مقاتل: \" أراد في قتل الأولاد واستحياء النساء شدة نحو قوله: ﴿إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ﴾⟪37:106⟫، نظر منه إلى منتهى الأية، وهو قوله: ﴿يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ﴾⟪2:49⟫، وكلا القولين صحيح، وقول السدي عن ابن عباس - رضي الله تعالى عنهما - أراد بقوله: \" بلاء \" أي نعمة أو نقمة تصريح أن الأمرين مرادان وليس قوله (أو) ههنا شكا منه كما ظنه بعض المفسرين، وقال إن ذلك شك من السدي، بل ذلك رواية عن ابن عباس - رضي الله تعالى عنهما - تنبيها منه أن النعمة والنقمة في هذه الجملة حاصلتان، وكل واحد منهما موجود فيها، وفي الآية تذكير لهم بما أولاهم من النعم في إنقاذهم من آل فرعون [وما كانوا يسومونهم من العذاب، وكان الأصل فيما روي لآن فرعون] رأى في المنام، أو قال له الكهنة: سيولد في هذا العام مولود يذهب بملكك، فجعل على كل عشر من النساء رجلا، فقال: انظروا إلى كل امرأة ولدت، فإن كان ذكرا، فاقتلوه، وإن كان أنثى فأبقوه، وكان ذلك أعظم للرزية كما قال الشعر:\nومن أعظم الرزء فيما أرى ...\nبقاء البنات وموت البنينا\nوقيل كان ذبحهم للأبناء استخدامهم في الأعمال القذرة الجارية مجرى أعظم الذبحين القتل، والإهانة، قال: وعلى ذلك قوله تعالى: ﴿إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ﴾⟪28:4⟫، وفيها حث لنا على تذكر نعمه ومراعاتها واحدة واحدة ، وتجديد الشكر لكل منها ...\n⟦1:187⟧"}, {"a": [50], "v": 1, "p": 187, "ev": 1, "ep": 189, "sid": 188, "t": "قوله - عز وجل -:\n﴿وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ﴾⟪2:50⟫ الآية: (50) سورة البقرة.\nالفرق، والفلق، لكن الفلق لا يكون إلا بين جسمين، والفرق: قد يكون في الأجسام والمعاني، وفي هذه القصة قد جاء اللفظان، قال تعالى: ﴿فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ﴾⟪26:63⟫ أي كل قطعة من الماء، والفرقان: كل كتاب يفرق بين الأحكام، وسمي عمر - رضي الله تعالى عنه - فاروقا لأجل أن النبي - صلى الله عليه وسلم - قضي ليهودي على منافق، فأتى عمر وقال \" إن محمدا قضى بيني وبين هذا، ولست أرضي قضاءه فاقض بيننا \"، فقال: أو رضيت قضائي؟ قال: نعم، فدخل داره، وأخرج السيف وحز رأسه، فنزل جبرائيل - عليه السلام - وقال: (إن عمر قد سمي في السماء فاروقا).\nوالبحر: استعير للسعة، فقيل: بحرت مذا أي: \" وسعته كسعته \"، وقيل بحرت الناقة: أي: شققت أذنها شقا واسعا، والباحر: الأحمق الموسع عليه من جهة رفع العقل عنه، وكأنه اعتبر في تسميته بلذك مقابلة العاقل، فقد جعل أسماء العقل كلها معتبرا فيه الضيق، والشدة، والفرق، والرسوب في المآثم شبه به غيره حتى قيل: غرق فلان في النعمة، وغرقه من اللبن أي مليء قدح، وأغرق في الشيء إذا تناهي والنظر نظران، نظر بصر، وبه يدرك المحسوسات ونظر بصيرة، وبه يدرك المعقولات، ونظر البصر كالخادم لنظر البصيرة فإن كان كلاهما سبيلا إلى المعرفة، والنظير أصله للمناظر، كأنه ينظر كل واحد من الناظرين إلى صاحبه في المشاكله، وناظرته: باريته في النظر، وأنظرته: تركته ينظر فيطلب، ومعنى الآية ما ذكره في قوله «فلما تراءى الجمعان قال أصحاب موسى» الآية، وفي قوله: فاضرب لهم طريقا في البحر يبسا}، وفي قوله تعالى: ﴿فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ﴾⟪26:63⟫، وقوله: ﴿وَأَنتُمۡ تَنظُرُونَ﴾⟪2:50⟫ لما كان النظر مترددا بين المحسوس الذي منه\n⟦1:188⟧\nالإبصار، والنظر المعقول الذي منه البصيرة، نظر كل واحد من المفسرين نظرا ما، فقال: من نظر نظر محسوس معناه (وأنتم تشاهدونه)، فقد روي أنه أفرد لكل سبط طريق من الماء وجعل الحاجز الذي بينه وبين الآخذ مشفا كالزجاج ينظرون منها إلى الآخرين، وقال بعضهم: قذف الماء بجثث آل فرعون بعد إغراقهم إلى الشط، فكان الناس ينظرون إليهم، وعلى ذلك حمل قوله: ﴿فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ﴾⟪10:92⟫، وقال: \" من نظر نظر معقول \" معناه: وأنتم تعتبرون بذلك، [وقيل معناه: \" وأنتم متمكنون من النظر، أي الاعتبار بذلك]، وقال بعضهم: في الآية مع إرادة هذا المعنى، أو النعمة المحسوسة التي أولاهم، إشارة إلى معنى آخر، وإلى نعمة معقولة أعطاهم، فإنه أشار بالبحر إلى الشبه التي تعتري وتفرقه إلى إزالتها، وبإغراق آل فرعون إلى إبطال الكفر، وبالنظر إلى المعرفة والتمكن منها بما أولاهم من البصرية والتمييز، وهذا الذي ذكره هذا [القائل] صحيح أنه تعالى فعله بهم اقتضاه لفظ الآية، أو لم يقتضه ...\n⟦1:189⟧"}, {"a": [51], "v": 1, "p": 189, "ev": 1, "ep": 190, "sid": 190, "t": "قوله - عز وجل -:\n﴿وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةٗ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ﴾⟪2:51⟫\nالآية (51) سورة البقرة.\nفرئ: \" واعدنا \" اعتبارا بالموعود وقبوله من الواعد وعده، فكان من كل واحد منهما وعدا، هذا بالإعطاء، وذلك بالقبول \" ووعدنا \" هو للاعتبار بالواحد دون الموعد، وعلى الثاني أكثر ما في القرآن نحو: ﴿إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ﴾⟪14:22⟫ ﴿وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ﴾⟪2:268⟫ ﴿وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ﴾⟪8:7⟫ وتقدير أربعين ليلة انقضاؤها كقولك: اليوم أربعون يوما منذ خرج زيد، أي تمامها، وقيل: إنما وعدهم ذلك في الأربعين، وأن لا يتجاوز هذا القدر، وهو الأصح، وقوله: ﴿وَوَٰعَدۡنَا مُوسَىٰ ثَلَٰثِينَ لَيۡلَةٗ وَأَتۡمَمۡنَٰهَا بِعَشۡرٖ﴾⟪7:142⟫ على ذلك، فإنه قيل له: يكون ذلك انقضاء ثلاثين، ثم كان عند الأربعين، فلم يكن في الوعد إخلاف، وإنما كان فيه بعض الإبهام، فلهذا التبس عليهم، وذكر تعالى عظم جهلهم، وأنهم بعدما أعطوا من البينات ورشحوا لما وعدوا، تهافتوا على عبادة عجل اتخذوه وقوله: وأنتم ظالمون: عنى به الظلم المطلق وهو الكفر، وقد تقدم الكلام في أنواع الظلم وأنها بالقول المحمل ثلاث أعظمها الكفر، وفي الآية حث على معرفة ما وعدنا الله تعالى به ومراعاته والمنع من الاشتغال عنه تعالى بشيء بغيره، وعلى هذا الوجه قال بعض الناس: كل ما شغلك عن الله فهو عجل متخذ وطاغوت متع وشيطان مطاع ومبدأ كل ذلك اتباع الهوى، ولذلك قال: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ﴾⟪38:26⟫ وقال وهذا وإن لم يكن كفرا فهو شرك وبهذا الوجع قال تعالى: ﴿وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ﴾⟪12:106⟫\n⟦1:190⟧\nوقوله - عزل وجل:"}, {"a": [52], "v": 1, "p": 190, "ev": 1, "ep": 191, "sid": 191, "t": "﴿ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ﴾⟪2:52⟫ سورة البقرة الآية (52) ...\nالعفو: القصد لتناول الشيء يقال: عفاه، واعتفاه وعفت الريح الدراري قصدته متناولة منها أثارها ولهذا المعنى قال الشاعر:\nأخذ البلى آياتها\nوإذ قيل: \" عفا فلان عن فلان \" كأنه قصد تناول شيء ما منصرفا عنه والمفعول به مترك لكونه غير مقصود وذلك كقولهم ذهبت عما ارتكبته وتجاوزت عنك: أي تجاوزت إلى شيء ما وعفا النبت والشعر أي قصد تناول الزيادة كقولهم: أخذ النبت في الزيادة وقولهم أعطى عفوا فعفوا مصدر في موضع الحال، أي أعطى وحاله حال العافي في الاهتزاز - إشارة إلى المعنى الذي عد بديعا للشعراء في نحو قول الشاعر:\nكأنك تعطيه الذي أنت سائله\nوالشكر: مقابلة الصنيعة بإظهار، ومنه: دابة شكور، إذا كانت مظهرة احسان صاحبها إليها، وضره شكري من ذلك والشكر: كناية عن الفرج المزوج، لكونه مقابلا للمهر مقابلة الشكر للمشكور عليه، والشكر ضرب من العدالة، إذ هو في مقابلة النعمة، وأعم من المكافآت فإن المكافأة يعتبر فيها تارة مماثلة في الكمية وتارة في حال المكافئ والمكافأ والشكر: لا يعتبر فيه ذلك.\nوأيضا فالشكر قد يكون باللسان تارة، وبالمقابلة تارة وقد تقدم الكلام في (لعل) وأنه وإن كان مقتضيا\n⟦1:191⟧\nللرجاء فليس على الاعتبار به تعالى، فإن الرجاء لمن يخفى عليه العواقب، ولا يتمكن من كل ما يريده، والقصد بالآية \" بتبين عفوه عنهم بعد ارتكابهم الجرائم ليتحروا شكره المقتضي لرحمته \" تنبيها لنا أن نراعي عفوه وإحسانه - راجين بلوغ شكره بالأفعال الحميدة، وقوله: ﴿مِّنۢ بَعۡدِ ذَٰلِكَ﴾⟪2:52⟫: أي من بعد اتخاذكم العجل، وإنما لم يقل: (ذلكم) لأ، كاف الخطاب إذا اتصل بالمبهمات يصير كوصله لها وجزاءا منها، فتارة يعتبر فيه الأصل فيجمع، وتارة يعتبر فيه كونه وصلة لا خطابا فيترك على حالته لا يثنى ولا يجمع."}, {"a": [53], "v": 1, "p": 191, "ev": 1, "ep": 192, "sid": 192, "t": "قوله - عز وجل -:\n﴿وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ﴾⟪2:53⟫ الآية (53) - سورة البقرة.\nالكتاب والفرقان: اسمان لشيء واحد لكن يقالان باعتبارين مختلفين أما الكتاب، فلجمع الأحكام المتفرقة فيه، وأما الفرقان: فلكونه مفرقا بين الحق والشبهة وبين الأحكام المختلفة، وأتى باللفظين تنبيها على تضمين التوراة للمعنيين وهذا أصح من قول من قال: تقديره: \" وإذ آتينا موسى الكتاب ومحمدا الفرقان \" فغن التوراة والقرآن كل واحد كتاب من وجه، وفرقان من وجه، وقد قال تعالى: ﴿وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ﴾⟪21:48⟫ وما قالوه من أن الفرقان أريد به فرق البحر فلا يمتنع إرادته مع ما تقدم، والإيتاء منقول عن: أتيت لكن تعورف في الإعطاء لما كان الإعطاء ضربان من الإيتاء وقد تقدم الكلام في \" لعل \" وفي الابتداء.\n⟦1:192⟧"}, {"a": [54], "v": 1, "p": 192, "ev": 1, "ep": 195, "sid": 193, "t": "قوله - عز وجل:\n﴿وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾⟪2:54⟫ الآية: (54) - سورة البقرة.\nقد تقدم الكلام في الظلم، فأما ظلم النفس، فقد يقال لكل فعل يباعدها عن توفيق الله تعالى في الدنيا وعن قوابه في الآخرة صغيرا كان أو كبيرا وقوله: ﴿وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ﴾⟪3:135⟫ وقوله: ﴿وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا﴾⟪4:110⟫\nفالأظهر أن فعل الفاحشة وعمل السوء للكبيرة، وظلم النفس في الآيتين للصغيرة.\nوفي الجملة: فإن ظلم النفس هو الخروج عن الاعتدال صغيرا كان أو كبيرا وقوله: \" تبارئكم \" فأصل البرء خلوص الشيء عن غيره إما على سبيل التقصي منه، أو على سبيل الإنشاء عنه فعلى التقصي قولهم: برئ فلان من مرضه، والبايع من عيوب مبيعه، وصاحب الدين من دينه، ومنه: استبراء الجارية، فإنه أراد تقصيها من \" ما \" ومن \" عسى \" أن قد غشيها من قبل، وعلى سبيل الإنشاء: قولهم: أبرأ الله الخلق وقوله تعالى : ﴿ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ﴾⟪59:24⟫ فإشارة إلى أحوال ثلاث، فالخلق: إلى إيجاد البدن، والبرء: إلى إيجاد الروح، وهي النسمة التي عناها أمير المؤمنين بقوله: \" والذي فلق الحبة، وبرأ النسمة \"، والتصوير إلى الجمع بينهما وإلى ثلاثتها أشار بقوله: ﴿إِنِّي خَٰلِقُۢ بَشَرٗا مِّن طِينٖ ۝ فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ﴾⟪38:71-72⟫ الآية وإلى ذلك أشار بقوله: ﴿يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ﴾⟪39:6⟫ وأما البرية فكثير من الناس ذهبوا إلى أنها منه، فترك همزة، كالذرية والنبي الخابية ومنهم من قال: البرى.\nأي التراب، أو من البرى، وإليه ذهب الكسائي قبرا هي اعتبارا بالأرواح، ويرى اعتبرا بالأشباح والقتل معروف وقد يستعمل في معنى\n⟦1:193⟧\nالتذليل وإزالة السورة، يقال: قتلت الدابة، أي: ذللتها، وقتلت الخمر: أزلت سورتها بالمزج، قال الشاعر:\nإن التي ناولتني فرددتها\n....\nقتلت قتلت فهاتها لم يقتل\nوفلان قتل فلانا، أي: مثله، فأصله مقاتلة، فتصور منه معنى المماثلة، لكون المقاتلين متماثلين في فعليهما المختص بهما، وإذ قيل: فلان قتل نفسه، فقد يقال: إذا فعل بنفسه فعلا أزال به الروح، وقد يقال إذ سلم نفسه للقتل، وإن كان أكثر ما يقال في ذلك المستقتل وقد يقال: إذ قيل من يختص به اختصاص نفسه نحو: فلم أقطع بهم إلا بنائي، وقوله: وإذا رميت يصيبني سهمي\nوقد يقال: قتل فلان نفسه، إذا ضيع حظها في طلب الآخرة، فأدى به ذلك إلى زوال حياته الأبدية، وذلك مذموم، وقد يقال في ضد ذلك وهو إذا أفنى شهوته وذلك هواه في الدنيا طلبا للآخرة، وذلك محمود، وعلى الاول قال جعفر بن محمد في قوله: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾⟪4:29⟫ أي: اطلبوا لها الحياة الأبدية، وعلى هذا قيل: \" قتل النفس إحياءها، وإحياءها قتلها، يعني في حالة وحالة، وروى أن الله تعالى أوحى إلى موسى (أن من أحبني قتلته، فقال يارب: إذا انتهيت في الخلة لم أبال بقتل الدنيا) وقال بعض الحكماء: \" من لم يعذب نفسه لم ينعمها ومن لم يقتلها لم يحبها (فاقتلوا أنفسكم) حملوه على أكثر هذه الوجوه، قال بعضهن: أمروا أن يجبا كل واحد نفسه بالسكين، وقيل: أمروا أن يسلم كل أحد للقتل، وقال أكثرهم: \" أمروا أن يقتل بعضهم بعضا فكان الرجل يقتل أباه وأخاه غير متحاش من ذلك قال بعضهم: أمروا أن يزيلوا شهواتهم ويفنوا نفوسهم الشهوية في الوصول إلى رضاء الرب ويبلغوا إلى الحياة الأبدية وقد طعن في هذه الآية بعض الملحدة، وزعم أن قتل\n⟦1:194⟧\nالنفس مستقبح في العقل، وهذا الجاهل إنما استقبحه لكونه جاهلا أن لنفوسنا خالقا بأمره نستبقيها وبأمره يقيها وأن لها بعد هذه الحياة التي هي لعب ولهو معادا إلى دار فيها حياة سرمدية كما قال: ﴿وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ﴾⟪29:64⟫ وإن قتلها بأمره يوصله إلى حياة خير منها ومن علم أن الإنسان في هذه الدنيا كمجاهد أقيم في ثغر يحرسه ووال على بلد يسوسه، وأنه مهما استرده [يعاد] فلا فرق بين أن يأمره بخروجه بنفسه أو يأمر غيره بإخراجه ومن تصور هذه الجملة علم أن الإنسان إنما أنكر له قتل نفسه في الدنيا لأنه كالراجع عن الثغر إلى حضرة صاحبه قبل استرداده، وإذا أمره أن يقتل نفسه - فقد رجع عنه بأمره وذلك ظاهر لمن تصور حالتي الدنيا والآخرة، وعرف قدر الحياتين والميتتين فيهما وقوله: ﴿ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ﴾⟪2:54⟫ الإشارة به إلى التوبة وقتل النفس ولما كان الشيء قد يكون خيرا عند الاعتبار بالدنيا شرا عند الاعتبار بالآخرة، وقد يكون على عكس ذلك.\nبين تعالى بقوله: ﴿ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ عِندَ بَارِئِكُمۡ﴾⟪2:54⟫ أن ذلك خير بالاعتبار بالأمور الإلاهية\nإن قيل: لم أعاد ذكر \" بارئكم \"؟\nوالإتيان بالضمير في مثله أحسن؟ قيل: إنما يحسن الضمير إذا لم يشتبه ولم يقصد بالتكرير تعظيم الأمر، وكان ذلك في جملة واحدة أو ما حكمه حكم الجملة الواحدة، فأما إذا لم يكن كذلك فتكريره أحسن وقد حصل ههنا الأحوال الثلاث فإنه جرى ذكر موسى والعجل فلو قيل عنده: يصح توهم إرادة أحدهما ثم قد علم أن المقصود في مثل هذا الموضع تفخيم الامر ثم قوله: ﴿ذَٰلِكَ خَيۡرٞ لَّكُمۡ﴾⟪58:12⟫ جملة أخرى غير الأولى ..\n⟦1:195⟧\nوقول الشاعر:\nلا أرى الموت يسبق الموت شيء\nوإنما استقبح لأنه قوله: يسبق الموت \" مفعول ثان \" لقوله: لا أرى الموت فصار المصراع كله جملة واحدة، والكلام في التوبة والثواب قد مضى، وعند قوله: (بارئكم) أي في حكمه وفيما يرتضيه نحو قوله تعالى: ﴿وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ﴾⟪3:78⟫ والشيء الذي يرتضيه تعالى تارة ينسب إليه، فيقال: [هو] له وتارة يقال: \" هو من عنده \" و \" هو عنده \" وقد بين في قوله: ﴿وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ﴾⟪2:51⟫ ما ارتكبوه من الذنب، وبين في هذه الآية ما قال لهم موسى - عليه السلام - عند ارتكابهم ذلك الذنب، وأن موسى - عليه السلام - مع تعظيم ما ارتكبوه لم يخلهم عن النصح لهم وتصريفهم بين بلاء النعمة والنقمة حسب ما أمره الله تعالى."}, {"a": [55], "v": 1, "p": 195, "ev": 1, "ep": 199, "sid": 196, "t": "قوله - عز وجل -:\n﴿وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ﴾⟪2:55⟫\nالآية (55) - سورة البقرة.\n[الرؤية] إدراك المرئي، وذلك على أوجه بحسب اختلاف قوى الإنسان فالأول [الرؤيا]\n⟦1:196⟧\nبالحاسة، وهو إدراك البصر، والثاني بالوهم والتخيل، نحو أرى أن زيدا منطلق، أي أتوهم، وقد يكون ذلك في اليقظة طورا، وفي المنام طورا، لكن يجعل اسم ما في المنام رؤيا، والثالث بالتفكير، والرابع بالعقل المشار إليه في قوله: ﴿ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ﴾⟪102:7⟫ فأما الرؤية الحسية على ما هي [عليه] في الدنيا من المقابلة، وكونها في جهة دون جهة فمنفية عن الباري سبحانه، إذ كان ذلك لا يصح إلا على جسم ذي لون وكيفية ولعدم اللون لا يبصر الهواء مع كونه جسما ولا يصح أيضا على الله الرؤية الوهمية إذ كان ذلك تصور هيئة محسوس كما تقدم أو مثل محسوس باطلا كتوهم إنسان طائر، وأما الفكرية فهي للعلماء في الدنيا وذلك إدراك المعرفة بالفكر [والرؤية] وإياه عنى أمير المؤمنين بقوله: \" لم تره العيون بشواهد الأبصار، ولكن رأته القلوب بحقائق الإيمان \"، وأما العقلية فإنها تحصل في الآخرة لكل أحد من حيث أنهم يضطرون إلى معرفته تعالى، لكن للمؤمنين حالة زائدة تقصر العبادة عنها، وهي المبشر بها في قوله عليه السلام:\n(ترون ربكم - عز وجل - كما ترون القمر ليلة البدر) والمشار إليها بقوله - عز وجل - ﴿إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَنَهَرٖ ۝ فِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكٖ مُّقۡتَدِرِۭ﴾⟪54:54-55⟫.\nولا يحصل في الدنيا إلا لبعض الأنبياء في بعض الأحوال، وذلك بتصور أفعاله تعالى مجردة عن أفعال المخلوقين بلا شبهة تعتريه ولتعري نفسه من الشهوات والهوى، ولكون ذلك لبعض الأنبياء في حال دون حال، قال عليه السلام:\n\" رأيت ربي في بعض طرقات المدينة \"، بمعنى وأنا فيها وقال تعالى:\n⟦1:197⟧\n﴿مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰٓ﴾⟪53:11⟫ وقوله ﴿وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ ۝ عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ﴾⟪53:13-14⟫ [أي وكان النبي عندها] وقال: ﴿مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ﴾⟪53:17⟫ وروى ابن عباس - رضي الله تعالى عنهما - \" أن محمدا - صلى الله عليه وسلم - رأى ربه مرتين \" وهذه الجملة إذا تصورت أسقطت الشبهة التي تعتري من لم يتصور الحقائق فاحتاج إلى رفع الأخبار الصحيحة والآثار الواضحة التي هي كأن عليها من شمس الضحى نورا ومن فلق الصباح عمودا وليس قوله تعالى إخبارا عن موسى - عليه السلام - في قوله: ﴿قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ﴾⟪7:143⟫ كما ظنه بعض الناس أن ذلك سأله لأن قومه كلفوه سؤاله أن يدركه محسوسا في الدنيا وكان يعلم أن ذلك محال، فإنه عليه السلام منزه عن أن يسئ لإساءة قومه، ويتجاهل اتباعا لجهلة تباعه، وإنما سأله هو الحالة التي كانت للنبي - صلى الله عليه وسلم - مرتين، وهذه إشارة يمكن مع الاستعانة بما تقدم آنفا أن يعرف معناه إلى أن ينتهي إليه، فنشرحه شرحا شافيا - إن شاء الله -، وأما الجهر: فالظهور لحاسة البصر أو حاسة السمع، فمن حاسة البصر، قيل: رأيته جهارا وتجاهروا بالأمر، وأجهرت فلانا وفلان يجهر بالمعاصي، وجهرت البئر أظهرت ماءها ومنه اشتق الجوهر، لكون أكثره ظاهرا للحواس فيمن لم يجعله منقولا عن الفارسية، ومن حاسة السمع، قيل: جهر فلان بقراءته، وكلام جهير، وهو جهوري الصوت والصاعقة والصاعقة يتقاربان إلا أن الصقع يقال في أصوات الأجسام الأرضية، والصعق فيما يكون من الجو والسماء وقال بعض أهل اللغة: الصاعقة\n⟦1:198⟧\nعلى ثلاثة أوجه، الموت: لقوله: ﴿فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ﴾⟪39:68⟫ وقوله: ﴿فَأَخَذَتۡهُمُ ٱلصَّٰعِقَةُ﴾ والثاني: العذاب لقوله: ﴿أَنذَرۡتُكُمۡ صَٰعِقَةٗ مِّثۡلَ صَٰعِقَةِ عَادٖ وَثَمُودَ﴾⟪41:13⟫ والثالث نار تسقط من السماء لقوله ﴿وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ﴾⟪13:13⟫ وهذا سوء تصور، لأن الصاعقة هي الصوت الشديد على ما تقدم، ثم قد يكون منه الموت تارة والعذاب تارة وتصحبه النار تارة، فإذا الموت، والنار والعذاب من يستفد من لفظ الصاعقة ويجب أن لا يلتبس علينا المعنى الذي وضع له اللفظ بالمعنى الذي يتبعه ويقتضيه، وليس بموضوع له بالقصد الأول، وهذا باب قد [يقع فيه السهو كثيرا على بعض ناقلي اللغة] وقد أحكم في غير هذا الكتاب، وقد بين الله تعالى في هذه الآية جهلهم بالباري وسؤالهم منه ما لا يصح سؤاله - تنبيها أن الجهل يرد بالإنسان أن يعتقد في الباري ما لا يصح عليه، ويرغب إليه بما لا يجوز أن يرغب به إليه وقد نبه على ذلك بأية أخرى تسكينا للنبي - عليه السلام - فيما سألوه جهلا منهم بقوله - عز وجل - ﴿يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ﴾⟪4:153⟫ الآية ..\n⟦1:199⟧"}, {"a": [56], "v": 1, "p": 199, "ev": 1, "ep": 199, "sid": 200, "t": "قوله - عز وجل -\n﴿ثُمَّ بَعَثۡنَٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ﴾⟪2:56⟫ الآية (56) - سورة البقرة.\nالبعث إرسال المبعوث عن المكان الذي فيه، لكن فرق بين تفاسيره بحسب اختلاف المعلق به، فقيل: بعثت البعير [من] مبركه، أي: أثرته، وبعثته في السير، أي: هيجته، وبعث الله الميت: أحياه، وضرب البعث على الجند إذا أمروا بالارتحال، وكل ذلك واحد في الحقيقة، وإنما اختلف لاختلاف صور المبعوثات، والموت حمل على المعروف وحمل أيضا على الأحوال الشاقة الجارية مجرى الموت، وليس يقتضي قوله: ﴿فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ﴾⟪2:55⟫ انهم ماتوا، ألا ترى إلى قوله تعالى: ﴿وَخَرَّ مُوسَىٰ صَعِقٗاۚ﴾⟪7:143⟫ لكن الآية تحتمل الأمرين، وحقيقة ما كان إنما يعتمد فيها على السمع المتعري عن الاحتمالات والكلام في ﴿لَعَلَّكُمۡ تَشۡكُرُونَ﴾⟪2:56⟫ قد تقدم، ونبه بالآية على أنه تعالى ينقذ من الشدائد عبده حالا فحالا تنبيها له من غفلته وإليه أشار بقوله: ﴿أَوَلَمۡ نُعَمِّرۡكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُۖ﴾⟪35:37⟫ .."}, {"a": [57], "v": 1, "p": 199, "ev": 1, "ep": 202, "sid": 200, "t": "وقوله - عز وجل -:\n﴿وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ﴾⟪2:57⟫ الآية (57) - سورة البقرة:\nالظل في الحقيقة عدم الصبح وسمي سواد الليل ظلا لعدم الصبح فيه والظلة كالصفة، والمظلة آلة يطلب بها الظل، و \" أظل فلان علينا حقيقته \" ألقى ظله علينا لدنوه منها واستعير الظل للمكان الذي فيه النعمة تصورا له في اليوم الصائف حتى قيل: فلان في ظل فلان، وقد أشار ابن عباس - رضي الله عنهما - إلى أن [الغمام] ههنا فيض الباري - عز وجل - وتوفيقه وإحسانه، فقال: هذا الغمام\n⟦1:200⟧\nالذي يأتي الله فيه المذكور في قوله: ﴿هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ﴾⟪2:210⟫ وهو الذي جاءت فيه الملائكة فيه يوم بدر وهذه إشارة منه عجيبة وأما المن: فمصدر من، أي أنعم وأصله من: مننت أي قطعت والمنة تتصور على وجهين، أحدهما: النعمة المقطوعة عن المنية، وعلى ذلك قول النبي - صلى الله عليه وسلم - \" وارغب لك رغبة من المال \" أي اقطع، والثاني: السبب الذي يقطع الشكر ويحرمه، وهو المعنى بقوله: ﴿لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ﴾⟪2:264⟫ وبقولهم: المنة تهدم الصنيعة والسلوى أصله ما يسلى الإنسان، ومنه السلوان والتسلي، وقال مجاهد: المن صمغة، وقال قتادة، وهو مثل الثلج، وقال الربيع: شراب كالعسل، وقال السدي: هو الزنجبيل، وقالوا: السلوى: طائر كالسماني، وأما قول ابن عباس - رضي الله عنهما - المن الذي يسقط من السماء على الشجر فيأكله الناس، والسلوى طائر، فقد قال بعضهم: إن ابن عباس - رضي الله عنهما - أشار بذلك إلى ما يرزق الله بني آدم من النبات واللحوم وسائر الخيرات، ودل على ذلك بهذين المثالين، قال وعلى هذا قول غيره إنما هو مثالات ..\nوقوله: ﴿كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ﴾⟪2:57⟫ قد تقدم الكلام في الرزق، وأنه بالنظر الخاصي ليس يتناول الأعراض الدنيوية فقط، بل جميع ما خولنا ومكننا منه من النعم الثلاث النفسية والبدنية والخارجية ولم يرد بالطيب المستطاب بحاستي الذوق والشم، بل المستطاب من كل وجه محسوسا ومعقولا وعاجلا وآجلا، والطيبات من الطعام هي المتناولة بحكم العقل والشرع من حيثما يسوغ تناوله في وقت ما يحتاج إليه [إلى تناوله وبقدر ما يحتاج] غير مسرف فيه ولا مشتغل به عما خلقنا لأجله ومتى تؤول على هذا الوجه يكون طيبا على الإطلاق وإلا فإن طاب من وجه خبث من وجه وعلى ذلك\n⟦1:201⟧\nقوله: ﴿كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا﴾⟪2:168⟫ وقوله ﴿قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ﴾⟪7:32⟫ وإذا عرف هذه الجملة علم أن من قال الطيبات اللذيذات نظر نظر حس، ومن قال الحلال والحرام نظر نظر معقول، وقوله: ﴿وَمَا ظَلَمُونَا﴾⟪2:57⟫ لما كان الله ذكر أفعالا تجري مجرى معاملات بينه وبين العباد كمعاملة العباد بعضهم مع بعض، من نحو الاستقراض في قوله: ﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا﴾ والابتياع في نحو: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫ ووصف نفسه بشكره لهم كشكرهم له ومحبته لهم كمحبتهم له ونصرته لهم كنصرتهم له، وموالاته لهم كموالاتهم له، وذكر مخادعته لهم كمخادعتهم له تعالى الله عن القبائح وسائر ذلك من الأفعال التي تجري بين المتكافئين بين تعالى أنه لا يعتقدن [به] معتقد أني إذا فعلت به فعلا حسنا مما إذا فعله إنسان بآخر ولم يقابله بمثله كان ظلما منه له أن يكون قد ظلمني في ذلك، ولكن قد ظلم نفسه وضيع حظه، إذ هو منزه أن يلحق نقيصة، إذ قيل: كيف يعلق قوله: ﴿وَمَا ظَلَمُونَا﴾⟪2:57⟫ بما تقدم قيل: معناه: قلنا لهم: ﴿كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ﴾⟪2:57⟫ فخالفوا، وما ظلمونا بمخالفتهم، وفي الآية تحذير لنا من كفران النهم وتلقيها بالبطر، وأن ما تعامله به من إساءة وإحسان فعائد علينا منافعه ومضاره ..\n⟦1:202⟧"}, {"a": [58], "v": 1, "p": 202, "ev": 1, "ep": 204, "sid": 203, "t": "قوله - عز وجل -:\n﴿وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُولُواْ حِطَّةٞ نَّغۡفِرۡ لَكُمۡ خَطَٰيَٰكُمۡۚ وَسَنَزِيدُ ٱلۡمُحۡسِنِينَ﴾⟪2:58⟫ الآية (58) - سورة البقرة.\nالدخول والولوج والتفحم والتوغل متقاربة، لكن الدخول عام، والولوج الدخول في مضيق والتفحم دخول في شدة، والتوغل في مشتبك شجر، وأوردت الإبل دخالا إذا تداخلت في الورود وفلان دخيل في القوم، وفيه دخل كناية عن الفساد، ودخول في مغمرة بالكلام، والدخل طائر صغير سمي بذلك لدخوله.\nخلال الشجر الملتفة، والحجر الضيقة، والقرية من قريت الشيء جمعت، وقيل أصله قرية، والقرى مجمع الماء، فكل بقعة يجتمع فيها الماء والأبنية قيل قرية، والمقرى للحوض، والقرى للحوضن والمكيلة، و (حطة) فعلة من حططت وقرى نصبا ورفعا، وبالنصب قيل هو مفعول بها نحو: قلت كلمة طيبة، وقيل هي في موضع سؤال أي: حط عنا ذنوبنا، نحو غفرا لنا، وبالرفع قيل هي حكاية، كأنه قيل: ما نسأله حطة، وقيل معناه هو مغلم تحطون فيه رحالكم، والغفر ستر بحائل ومنه المغفر للبيضة والغفارة لخرقة يغطي بها الرأس ولما تلف على سنة القوس، وغفر المريض \" نكس كأنه غطى المرض على عقله أو على صحته، وغفر ذنبه استعارة في الأصل، كقولهم: \" ليست عليه ذيلي، والخطايا على ضروب أحدها أن يريد غير ما يحسن إرادته ويفعله فهذا هو الخطأ التام [من كل وجه] المأخوذ به الإنسان والثاني أن يريد ما يجوز فعله، لكن وقع منه خلاف ما أراد فيقال:\n⟦1:203⟧\nأصاب في الإرادة، وأخطأ في الفعل، وهو المعنى بقوله: عليه السلام: (رفع عن أمتي الخطأ والنسيان)، وقوله: (من اجتهد فأخطأ فله أجر)، والثالث: أن يريد ما لا يحسن فعله ويتفق منه خلافه، فهذا مذموم لقصده وغير محمود على فعله، وجملة الأمر أنه يقال لمن أراد شيئا فأنفق منه خلافه أنه أخطأ، وإذا وقع منه، كما أراده أنه اصاب الخطأ ويقال لمن - فعل فعلا لا - حسن أو أراد إرادة لا - حسن أنه أخطأ ولهذا يقال - أصاب فأخطأ الصواب، وأصاب الصواب وأخطأ الخطأ، فإذا هذه اللفظة مشتركة كما ترى، مترددة بين معاني يجب لمن يتحرى الحقائق تأمله، فهي مشكلة جدا، وقال بعض أهل اللغة: يقال خطئ إذا أصاب ما أراده من الخطأ، وأخطأ إذا أراده ولم يصبه، والحسن سقال لما يألفه البصر أو تألفه البصيرة، وأحسن إذا فعل ما استحسنه أحد هذين، وقد تقدم أن الإحسان زائد على العدالة، لأن العادل هو الذ يفعل ما إذا أخل به تلحقه المذمة، والمحسن من زاد على ذلك، ولذلك قيل: \" عدل الله كله إحسان \" وورد في التفسير أنهم أمروا بدخول بيت المقدس من باب القبة منحنين، وقيل ساجدين، وأن يستغفروا، وذكر بعض المحققين أن الإشارة مع إرادة الظاهر بدخول القرية إلى الدخول تحت حجر الشريعة، وبالأكل إلى تحري ما يبلغهم إلى العيش الرغد.\nوبدخول الباب سجدا سلوك الاستقامة على التذلل والتخضع، وبقوله: (حطة) إلى الاستغفار قولا وفعلا طلبا الذنوب، وقال بعضهم: الإشارة به إلى التحقق بالعلم الذي أتاهم به موسى - عليه السلام - وتناولهم منه والتمسك به فهو الحلال الحلو الذي يتناول بلا خطر، إذ إن جميع المتناولات في\n⟦1:204⟧\nتناوله مزاحمة البعض بعض ومنع الغير على وجه آلاء العلم، فإنه يمكن لكل واحد أن يتناول كل جزء منه بلا منع منه للآخر، وأمر بسلوك طرقه على ما يجب، وذلك بأن لا يقدم ما يجب أن يؤخر أو يؤخر ما شأنه أن يقدم، وعلى ذلك قوله - عز وجل -: ﴿وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ﴾⟪2:189⟫، والإشارة بالقرية إلى العلم كإشارة النبي - عليه السلام بالمدينة إليه حيث قال: \" أنا مدينة العلم وعلي بابها \"، وهذان القولان يتقاربان، فإن العلم والعمل يتلازمان، وبهما يتم الإيمان، لكن الأول نظر إلى المنتهى الذي هو العمل، والثاني نظر إلى المبدأ الذي هو العلم، وبحسب هذه الآية قوله تعالى: ﴿ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ﴾⟪5:21⟫ .."}, {"a": [59], "v": 1, "p": 204, "ev": 1, "ep": 206, "sid": 205, "t": "قوله - عز وجل -:\n﴿فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ﴾⟪2:59⟫\nالآية (59) - سورة البقرة:\nالتبديل والتغيير يتقاربان، لكن أكثر ما يقال التبديل في شيء يجعل مكان آخر، والتغيير في حالة للشيء تغير كالماء الحار إذا جعل باردا، وقيل: الأبدال من الناس هم قوم يجعلهم الله مكان آخرين ممن هم [المعنيون من العالم] الذين بدلوا أحوالهم البهيمية بالأحوال الملكية حسب الطاقة، والرجز: الرجس والنجس يتقاربان معانيها بتقارب ألفاظها نحو: السراط والزراط، والبراق والبساق، وأصل ذلك لما يعاف ذوقا أو شما أو عقلا أو شرعا، فالكريه بالعقل والشرع يعبر عنه بالخبيث والقذر ونحو ذلك، كما يعبر عن ضده بالطيب والنظيف، وعلى ذلك قوله: ﴿إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ﴾⟪9:28⟫، وقوله\n⟦1:205⟧\nتعالى: ﴿إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ﴾⟪5:90⟫، فإن بعض ذلك كريه بالطبع، وبعض كريه بالشرع، وسمي العذاب رجزا في قوله: ﴿لَئِن كَشَفۡتَ عَنَّا ٱلرِّجۡزَ﴾⟪7:134⟫، ورجسا في قوله: ﴿وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ﴾⟪9:125⟫، ومن قال: ليس الرجس النتن، فقد زصف الله الخمر بذلك، وهي طيبة الرائحة، وقد وصف الله تعالى [خمرا] في الجنة باللذة، [فإن هذا القائل] بعيد التصور للوهمات فضلا عن المعقولات، وهذه الجملة إذا تصورت علم أن الكسائي لما قال: الرجس النتن، والرجز العذاب، والزجاج لما قال الرجس قد يجئ للعذاب كله قريب، وإنما اختلافهم لنظرهم إلى مواقع الكلمات لا إلى موضوعها في أنفسها، وكونها مستعارة من المحسوس للمعقول، وأما تبديلهم، فقد قيل إنه قيل لهم: قولوا حطة، فقالوا استهزاء حنطة، وقيل لهم: ﴿وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا﴾⟪2:58⟫ فدخلوا مقعين على أستاهم، والإشارة بلذك في الجملة أنهم غيروا ما شرع لهم ولم يراعوا أمر الله تعالى، فأنزل الله بهم عليهم العذاب، وتخصيص قوله: ﴿رِجۡزٗا مِّنَ ٱلسَّمَآءِ﴾⟪2:59⟫ هو أن العذاب ضربان، ضرب قد يمكن على بعض دفاعه أو يظن أنه يمكن فيه ذلك، وهو كل عذاب على يد آدمي أو من جهة المخلوقات كالهدم والغرق، وضرب لا يمكن ولا يظن دفاعه بقوة آدمي كالطاعون والصاعقة والموت، والوحي وهو المعني بقوله ﴿رِجۡزٗا مِّنَ ٱلسَّمَآءِ﴾⟪2:59⟫\nإن قيل: لم قال: ﴿فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ﴾⟪2:59⟫ ولم يقل: (فأنزلنا عليهم) مع أنه كان أوجز؟ قيل: قصدا إلى\n⟦1:206⟧\nأن يبين أن إنزال الرجز كان لظلمهم لا للإبدال فقط، فإن الإبدال بعد الظلم، ثم بين بقوله: ﴿بِمَا كَانُواْ يَفۡسُقُونَ﴾⟪2:59⟫ أن ذلك الظلم الذي تعاطوه كان فسقا منهم، \" والله الموفق \" ..."}];
